  var tree = Array.ofDim[Int](500001,3)

  def insert(i:Int, j:Int):Unit =
    if(tree(i)(0) > tree(j)(0)) {
      if(tree(i)(1) == -1) tree(i)(1) = j
      else insert(tree(i)(1), j)
    } else {
      if(tree(i)(2) == -1) tree(i)(2) = j
      else insert(tree(i)(2), j)
    }

  def inOrder():Unit = {
    var stack:List[Array[Int]] = Nil
    var curr = 0
    var flg = true

    while(flg) {
      while(curr != -1) {
        stack = tree(curr)::stack
        curr = tree(curr)(1)
      }
      if(curr == -1 && stack != Nil) {
        val item = stack.head
        stack = stack.tail
        print(" "+item(0))
        curr = item(2)
      } else {
        flg = false
      }
    }
  }

  def scan(list:List[Array[Int]]):Unit = {
    list match {
      case Nil => ()
      case hd::tl => {
        print(" "+hd(0))
        val hd2 = if(hd(2) != -1) tree(hd(2))::tl else tl
        val hd3 = if(hd(1) != -1) tree(hd(1))::hd2 else hd2
        scan(hd3)
      }
    }
  }

  def preOrder(i:Int):Unit =
    if(i == -1) return
    else scan(tree(i)::Nil)

  def main(args:Array[String]) = {
    val n = readInt
    var j = 0

    for(i<-0 until n) {
      val s = readLine.split(" ")
      s(0) match {
        case "insert" => {
          tree(j) = Array(s(1).toInt,-1,-1)
          if(j!=0) insert(0, j)
          j+=1
        }
        case _ => {
          inOrder();println
          preOrder(0);println
        }
      }
    }
  }
}

import scala.io.StdIn

object Main extends App {

  val n = StdIn.readLine().trim.toInt
  var root: Node = null

  case class Node(key: Int, var parent: Node, var left: Node, var right: Node){
    private def getDefaultKey(p: Node) = if(p == null) -1 else p.key
    override def toString: String = s"Node($key, ${getDefaultKey(parent)} ${getDefaultKey(left)} ${getDefaultKey(right)})"
  }

  (0 until n).foreach { _ =>
    val command = StdIn.readLine()
    command.split(' ') match {
      case Array("insert", key) => insert(Node(key.toInt, null, null, null))
      case _ => {
        // print
        inorder(root)
        println("")
        preorder(root)
        println("")
      }
    }
  }


  def insert(z: Node) = {
    var y:Node = null
    var x:Node = root
    while(x != null){
      y = x
      if(z.key < x.key){
        x = x.left
      } else {
        x = x.right
      }
    }
    z.parent = y

    if(y == null){
      root = z
    } else if(z.key < y.key){
      y.left = z
    } else {
      y.right = z
    }
  }

  def preorder(n: Node): Unit = {
    print(" " + n.key)
    if(n.left != null) preorder(n.left)
    if(n.right != null) preorder(n.right)
  }

  def inorder(n: Node): Unit = {
    if(n.left != null) inorder(n.left)
    print(" " + n.key)
    if(n.right != null) inorder(n.right)
  }

}

import java.io._
import scala.io.StdIn.{readInt, readLine}

object Main {
  val out:BufferedWriter =
    new BufferedWriter(new OutputStreamWriter(new FileOutputStream(java.io.FileDescriptor.out), "ASCII"), 512)
  var count = 0
  class Node(var key:Int, var left:Node = null, var right:Node = null) { }

  def insert(tree:Node, key:Node) = {
    val keyNode = key
    def loop(node:Node):Node =
      if(node.key > keyNode.key) {
        if(node.left == null) node
        else loop(node.left)
      } else {
        if(node.right == null) node
        else loop(node.right)
      }

    val target = loop(tree)

    if(keyNode.key < target.key) target.left = keyNode
    else target.right = keyNode
  }

  def inOrder(root:Node):Unit = {
    var stack:List[Node] = Nil
    var curr = root
    var flg = true

    while(flg) {
      while(curr != null) {
        stack = curr::stack
        curr = curr.left
      }
      if(curr == null && stack != Nil) {
        val item = stack.head
        stack = stack.tail
        out.write(" ")
        out.write(item.key.toString)
        if(count<100) count += 1
        else {
          out.flush
          count = 0
        }
        curr = item.right
      } else {
        flg = false
      }
    }
  }

  def scan(list:List[Node]):Unit = {
    list match {
      case Nil => ()
      case hd::tl => {
        out.write(" ")
        out.write(hd.key.toString)
        if(count<100) count += 1
        else {
          out.flush
          count = 0
        }
        val hd2 = if(hd.right!=null) hd.right::tl else tl
        val hd3 =if(hd.left!=null) hd.left::hd2 else hd2
        scan(hd3)
      }
    }
  }

  def preOrder(tree:Node):Unit =
    if(tree == null) return
    else  scan(tree::Nil)

  def main(args:Array[String]) = {
    val n = readInt
    val tree = new Node(-1)

    for(i<-0 until n) {
      val s = readLine.split(" ")
      s(0) match {
        case "insert" =>
          if(tree.key == -1) tree.key = s(1).toInt
          else insert(tree, new Node(s(1).toInt))
        case _ => {
          inOrder(tree)
          out.write("\n")
          out.flush()
          preOrder(tree)
          out.write("\n")
          out.flush()
        }
      }
    }
  }
}

