sealed trait BTree {
  def insert(x: Int): BTree
  def preorder: List[Int]
  def inorder: List[Int]
  def show: Unit = {
    println(" " + this.inorder.mkString(" "))
    println(" " + this.preorder.mkString(" "))
  }
}
object Empty extends BTree {
  def insert(x: Int): BTree = new Node(x, Empty, Empty)
  def preorder: List[Int] = Nil
  def inorder: List[Int] = Nil
}
class Node(v: Int, l: BTree, r: BTree) extends BTree {
  def insert(x: Int): BTree =
    if (x < v) new Node(v, l.insert(x), r)
    else new Node(v, l, r.insert(x))
  def preorder: List[Int] = v :: (l.preorder ::: r.preorder)
  def inorder: List[Int]  = l.inorder ::: (v :: r.inorder)
}

