Node Cre(int x){
    Node temp;
    temp = new List(0);
    temp->p = x;
    return temp;
}

Node push(Node head, int x){
    if (head == NULL) {
        head = Cre(x);
        return head;
    }

    Node t = head, last = NULL;
    while (t != NULL){
        last = t;
        if (x < t->p) t = t->left;
        else t = t->right;
    }
    Node temp = Cre(x);
    if (x < last->p)
        last->left = temp;
    else
        last->right = temp;
    return head;
}

