struct Node {
  int key_;
  Node *left_, *right_;
  Node *parent_;

  Node(int key) : key_(key), left_(0), right_(0) {}
  Node() : key_(0), left_(0), right_(0) {}
  ~Node()
  {
    if (left_) { delete left_; left_ = 0; }
    if (right_) { delete right_; right_ = 0; }
    parent_ = 0;
    //fprintf(stderr, "DEBUG: deleting %d\n", key_);
  }

  void print_inorder()
  {
    if (left_) { left_->print_inorder(); }
    fprintf(stdout, " %d", key_);
    if (right_) { right_->print_inorder(); }
  }

  void print_preorder()
  {
    fprintf(stdout, " %d", key_);
    if (left_) { left_->print_preorder(); }
    if (right_) { right_->print_preorder(); }
  }
};

class BST {
public:
  BST() : root_(0) {}
  ~BST() { delete root_; }

  void insert(Node *node)
  {
    Node *x = root_, *y = 0;
    while (x != 0) {
      y = x;
      if (node->key_ < x->key_) {
        x = x->left_;
      }
      else if (node->key_ > x->key_) {
        x = x->right_;
      }
      else {
        // duplicate node
        return;
      }
    }
    node->parent_ = y;

    if (y == 0) { root_ = node; }
    else if (node->key_ < y->key_) {
      y->left_ = node;
    }
    else if (node->key_ > y->key_) {
      y->right_ = node;
    }
  }

  void print_inorder()
  {
    if (root_) {
      root_->print_inorder();
      fprintf(stdout, "\n");
    }
  }

  void print_preorder()
  {
    if (root_) {
      root_->print_preorder();
      fprintf(stdout, "\n");
    }
  }

private:
  Node *root_;
};

