  BST tree;
  for (int i = 0; i < n; ++i) {
    fscanf(stdin, "%s", buf);
    if (buf[0] == 'i') {
      fscanf(stdin, "%d", &key);
      tree.insert(new Node(key));
    }
    else if (buf[0] == 'p') {
      tree.print_inorder();
      tree.print_preorder();
    }
  }
  return 0;
}

