using namespace std;

struct BSTNode {
	int key;
	BSTNode *lchild, *rchild, *parent;
	BSTNode(int k, BSTNode *p = nullptr, BSTNode *l = nullptr, BSTNode *r = nullptr) : key(k), lchild(l), rchild(r), parent(p)
	{}
};
typedef BSTNode* BSTree;

BSTree insert(BSTree& Root, int key)
{
	BSTree parent = nullptr;
	BSTree child = Root;
	while (child)
	{
		parent = child;
		if (key > child->key)
			child = child->rchild;
		else
			child = child->lchild;
	}
	child = new BSTNode(key, parent);
	if (!parent)
		Root = child;
	else if (parent->key > key)
		parent->lchild = child;
	else
		parent->rchild = child;
	return child;
}
void pre_order(BSTree T)
{
	printf(" %d", T->key);
	if (T->lchild)
		pre_order(T->lchild);
	if (T->rchild)
		pre_order(T->rchild);
}
void in_order(BSTree T)
{
	if (T->lchild)
		in_order(T->lchild);
	printf(" %d", T->key);
	if (T->rchild)
		in_order(T->rchild);
}
int main(void)
{
	char buf[10];
	int key, n;
	scanf("%d", &n);
	BSTree T = nullptr;
	while (n--)
	{
		scanf("%s", buf);
		if (*buf == 'i')
		{
			scanf("%d", &key);
			insert(T, key);
		}
		else
		{
			in_order(T);
			putchar('\n');
			pre_order(T);
			putchar('\n');
		}
	}
	return 0;
}

