class BinarySearchTree {

	typedef struct Node {
		int key;
		Node *parent, *left, *right;
		Node() {}
		Node(int key, Node* parent, Node* left, Node* right) : key(key), parent(parent), left(left), right(right) {}
	}*NodePtr;

	NodePtr root;

public:

	BinarySearchTree() : root(NULL) {}

	void insert(int key) {
		NodePtr z = new Node(key, NULL, NULL, NULL);
		NodePtr y = NULL;
		NodePtr x = root;
		while (x != NULL) {
			y = x;
			if (z->key < x->key)
				x = x->left;
			else
				x = x->right;
		}
		z->parent = y;

		if (y == NULL)
			root = z;
		else if (z->key < y->key)
			y->left = z;
		else
			y->right = z;
	}

	void printInorder(NodePtr node) {
		if (node == NULL)
			return;
		printInorder(node->left);
		cout << " " << node->key;
		printInorder(node->right);
	}

	void printInorder() {
		printInorder(root);
	}

	void printPreorder(NodePtr node) {
		if (node == NULL)
			return;
		cout << " " << node->key;
		printPreorder(node->left);
		printPreorder(node->right);
	}

	void printPreorder() {
		printPreorder(root);
	}

};

