}

void print_inorder(const vector<pair<int, int> >& nodes,  const vector<int>& node_val, const int r){
  if(r<0) return;
  print_inorder(nodes, node_val, nodes[r].first);
  cout << ' ' << node_val[r];
  print_inorder(nodes, node_val, nodes[r].second);
}


void print_postorder(const vector<pair<int, int> >& nodes, const int r, int geta, bool& first_print){
  if(r<0) return;
  print_postorder(nodes, nodes[r].first, geta, first_print);
  print_postorder(nodes, nodes[r].second, geta, first_print);

  cout << (first_print ? "": " ")  << (r+geta);
  first_print = false;
}

