      //h>0, r>=0
      node_val[h] = v;
      nodes[h].first = nodes[h].second = -1;

      int* p = &r;
      while(*p >= 0){
	if(node_val[*p] <= node_val[h]){
	  p = &(nodes[*p].first);
	}
	else{
	  p = &(nodes[*p].second);
	}
      }

      //*p < 0
      *p = h;
      ++h;
    }
