void insert(Tree* T, TreeNode* z){
  TreeNode* y = T->nil;
  TreeNode* x = T->root;
  while ( x != T->nil ){
   y = x;
   if ( z->value < x->value )
     x = x->left;
   else
     x = x->right;
  }
  z->parent = y;


  if ( y == T->nil )
    T->root = z;
  else if ( z->value < y->value )
    y->left = z;
  else 
    y->right = z;
}

