class BinaryTree
{
public :
    int key;

    BinaryTree(void) : m_pHead(NULL) {};
    void Insert(int key);
    void PrintInorder(void);
    void PrintPreorder(void);

private :
    stNode *m_pHead;
    void Inorder(stNode *pNode);
    void Preorder(stNode *pNode);
};

void BinaryTree::Insert(int key)
{
    stNode *pNode, *pFind;

    pNode = (stNode*)malloc(sizeof(stNode));
    pNode->key    = key;
    pNode->pLeft  = NULL;
    pNode->pRight = NULL;

    if (m_pHead != NULL) {
        pFind = m_pHead;
        for (;;) {
            if (key < pFind->key) {
                if (pFind->pLeft == NULL) {
                    pFind->pLeft = pNode;
                    break;
                }
                else {
                    pFind = pFind->pLeft;
                }
            }
            else {
                if (pFind->pRight == NULL) {
                    pFind->pRight = pNode;
                    break;
                }
                else {
                    pFind = pFind->pRight;
                }
            }
        }

        pNode->pParent = pFind;
    }
    else {
        m_pHead = pNode;
        pNode->pParent = NULL;
    }

    return;
}

void BinaryTree::PrintInorder(void)
{
    Inorder(m_pHead);
    printf("\n");
    return;
}

void BinaryTree::PrintPreorder(void)
{
    Preorder(m_pHead);
    printf("\n");
    return;
}

