	if(T.size() == 0){
		binaryTree x = {key, -1, -1, -1};
		T.push_back(x);
	}else{
		int y = 0;
		bool flag = true;
		while(flag){
			if(T[y].key > key){
				if(T[y].left == -1){
					T[y].left = T.size();
					binaryTree x = {key, -1, -1, y};
					T.push_back(x);
					flag = false;
				}else{
					y = T[y].left;
				}
			}else{
				if(T[y].right == -1){
					T[y].right = T.size();
					binaryTree x = {key, -1, -1, y};
					T.push_back(x);
					flag = false;
				}else{
					y = T[y].right;
				}
			}
		}
	}
}

