void ins(unique_ptr<tree>&t, int num) {
	if (t == nullptr) {
		t = make_unique<tree>(num);
	}
	else {
		if (num < t->value) {
			ins(t->ltree, num);
		}
		else {
			ins(t->rtree, num);
		}
	}
}
void dfs(unique_ptr< tree>&t,bool mid,vector<int>&v) {
	if (mid) {
		v.emplace_back(t->value);
	}
	if (t->ltree) {
		dfs(t->ltree, mid, v);
	}
	if (!mid) {
		v.emplace_back(t->value);
	}
	if (t->rtree) {
		dfs(t->rtree, mid, v);
	}

	return;
}

