		*root = data;
		return;
	}
	Node* prev = NULL;
	Node* node = *root;
	while (node != NULL) {
		prev = node;
		if (node->key > data->key) {
			node = node->left;
		}
		else {
			node = node->right;
		}
	}
	if (prev->key > data->key) {
		prev->left = data;
	}
	else {
		prev->right = data;
	}
}

