using namespace std;

struct TNode
{
	int Id;
	TNode* Parent;
	TNode* LChild;
	TNode* RChild;
};

struct TTree
{
private:
	void Delete(const TNode* Node)
	{
		if(Node == NULL) return;
		Delete(Node->LChild);
		Delete(Node->RChild);
		delete Node;
	}
public:
	TNode* Root;
	TTree()
	{
		Root = NULL;
	}
	~TTree()
	{
		Delete(Root);
	}
};

void Insert(TTree& Tree, TNode* z)
{
    assert(z != NULL);
	TNode* y = NULL;
	TNode* x = Tree.Root;
	while(x != NULL){
		y = x;
		if(z->Id < x->Id){
			x = x->LChild;
		}else{
			x = x->RChild;
		}
	}
	z->Parent = y;
	if(y == NULL){
		Tree.Root = z;
	}else if(z->Id < y->Id){
		y->LChild = z;
	}else{
		y->RChild = z;
	}
}

