	Node* BST = NULL;

	for (int i=0; i<n; i++) {
		//std::cout << BST << std::endl;
		std::string buf;
		getline(std::cin, buf);
		int pos = buf.find(' ', 0);
		if (pos == std::string::npos) {
			// print
			walk_inorder(BST); std::cout << std::endl;
			walk_preorder(BST); std::cout << std::endl;
		}
		else { // insert
			int key = std::stoi(buf.substr(pos+1));
			Node* z = new Node(key);
			//std::cout << "node " << i << ": " << z << std::endl;
			insert(&BST, z);
		}
	}

	deleteNodes(BST);

	return 0;
}

