void Init(){
  rep(i,500005){
    p[i]=left2[i]=right2[i]=key[i]=NIL;
  }
}


int FindRoot(){
  rep(i,n){
    if(p[i] == NIL){
      return i;
    }
  }
}



void TREE_INSERT(int z){
  int y = NIL;  
  int x = root;

  while(x != NIL){
    y = x;
    if(key[z] < key[x]){
      x = left2[x];
    }
    else x = right2[x];
  }
  p[z]=y;
  if(y == NIL){
    root = z;
  }
  else if(key[z] < key[y]){
    left2[y] = z;
  }else{
    right2[y] = z;
  }

}

void InorderTreeWalk(int x){
  if(x != NIL){
    InorderTreeWalk(left2[x]);
    printf(" %d",key[x]);
