void add(node** root,int a) {
	node *newnode = new node;
	node* now = *root;
	newnode->id = a;
	newnode->left = NULL;
	newnode->right = NULL;
	if (now == NULL) {
		newnode->parent = NULL;
		*root = newnode;
		return;
	}
	while (1) {
		if (now->id > a) {
