#define MAX 500000

class Node
{
public:
	enum TYPE { ROOT, INTERNAL_NODE, LEAF };
	Node(int ID, Node* PARENT)
	{
		id = ID;
		parent = PARENT;
	}
	~Node() {};
	Node* parent = 0;
	Node* sibling = 0;
	Node* left = 0;
	Node* right = 0;
	int id;
	int degree = 0;
	int depth = -1;
	int height = -1;
	TYPE type;
};

class Tree
{
public:
	Tree() 
	{
		nodes = new Node*[MAX];
		for (int i = 0; i < MAX; i++)nodes[i] = 0; 
	}
	~Tree() 
	{
		for (int i = 0; i < MAX; i++)if (nodes[i] != 0)delete nodes[i]; 
	}
	void CreateNode(int ID, Node* PARENT) { nodes[ID] = new Node(ID, PARENT); }
	void Insert(int N, Node* NODE)
	{
		if (NODE->id < N)
		{
			if (NODE->right == 0)
			{
				CreateNode(N, NODE);
				NODE->right = nodes[N];
				nodes[N]->parent = NODE;
			}
			else Insert(N, NODE->right);
		}
		else
		{
			if (NODE->left == 0)
			{
				CreateNode(N, NODE);
				NODE->left = nodes[N];
				nodes[N]->parent = NODE;
			}
			else Insert(N, NODE->left);
		}
	}
	Node** nodes;
	Node* nodes_root;
	void SetRoot()
	{
		for (int i = 0; i < MAX; i++)
		{
			if (nodes[i] == 0)break;
			if (nodes[i]->parent == 0)
			{
				nodes[i]->type = Node::ROOT;
				nodes[i]->depth = 0;
				nodes_root = nodes[i];
				break;
			}
		}
	}
	void ShowPreoder(Node* NODE)
	{
		printf(" %d", NODE->id);
		if (NODE->left != 0) ShowPreoder(NODE->left);
		if (NODE->right != 0) ShowPreoder(NODE->right);
	}
	void ShowInoder(Node* NODE)
	{
		if (NODE->left != 0) ShowInoder(NODE->left);
		printf(" %d", NODE->id);
		if (NODE->right != 0) ShowInoder(NODE->right);
	}
	void ShowPostoder(Node* NODE)
	{
		if (NODE->left != 0) ShowPostoder(NODE->left);
		if (NODE->right != 0) ShowPostoder(NODE->right);
		printf(" %d", NODE->id);
	}

};

