#define NIL nullptr

struct Node {
  int key;
  Node *parent, *left, *right;

  Node(int key) : key(key) { parent = left = right = NIL; }
  ~Node() {
    if (right != NIL)
      delete right;
    if (left != NIL)
      delete left;
  }
};

Node *getRoot(Node *t) {
  Node *n = t;
  while (t->parent != NIL) {
    n = n->parent;
  }
  return n;
