		}

		cout << " " << node_id;

		if(p_node.p_right_child != NULL){
			//cout << "print right branch\n";
			printInorder(p_node.p_right_child->id);
		}
	}

	void printInorderTree(){
		printInorder(root_id);
	}

	void printPreorder(int node_id){
		Node& p_node = node_map[node_id];
		cout << " " << node_id;

