    value = k;
    parent = p;
    left = l;
    right = r;
  }
};

Node *root = nullptr;

void insert(Node *n, int k) {
  Node *t = new Node(k, n, nullptr, nullptr);

  if (n == nullptr) {
    t->parent = nullptr;
    root = t;
    return;
  }
  if (k < n->value) {
    if (n->left == nullptr) {
      n->left = t;
    } else {
      delete t;
      insert(n->left, k);
    }
  } else {
    if (n->right == nullptr) {
      n->right = t;
    } else {
      delete t;
      insert(n->right, k);
    }
  }
}

