#include <cstdlib>

struct Node {
  struct Node *right;
  struct Node *left;
  struct Node *parent;
  int key;
};

void print_key(struct Node *node, bool *first) {
  if (!(*first)) {
    std::cout << " ";
  } else {
    *first = false;
  }

  std::cout << node->key;  
}

struct Node *insertNode(struct Node *root, int k){
  struct Node *y = NULL;
  struct Node *x = root;
  struct Node *newNode;

  newNode = (struct Node *) std::malloc(sizeof(struct Node));

  newNode->right = NULL;
  newNode->left = NULL;
  newNode->parent = NULL;
  newNode->key = k;

  while (x != NULL) {
    y = x;

    if (newNode->key < x->key) {
      x = x->left;
    } else {
      x = x->right;
    }
  }

  newNode->parent = y;

  if (y == NULL) {
    root = newNode;
  } else if (newNode->key < y->key) {
    y->left = newNode;
  } else {
    y->right = newNode;
  }

  return root;
}

void printByInorder(struct Node *root, bool *first) {
  if (root == NULL) {
    return;
  }

  if ((root->left == NULL) && (root->right == NULL)) {
    print_key(root, first);
    return;
  }

  printByInorder(root->left, first);
  print_key(root, first);
  printByInorder(root->right, first);
}

void printByPreorder(struct Node *root, bool *first) {
  if (root == NULL) {
    return;
  }

  if ((root->left == NULL) && (root->right == NULL)) {
    print_key(root, first);
    return;
  }

  print_key(root, first);
  printByPreorder(root->left, first);
  printByPreorder(root->right, first);
}

int main(){
  int n = 0;
  struct Node *root = NULL;

  std::cin >> n;

  for (int i = 0; i < n; i++) {
    std::string command;

    std::cin >> command;

    if (command.at(0) == 'p') {
      bool first = true;
      printByInorder(root, &first);

      std::cout << std::endl;

      first = true;
      printByPreorder(root, &first);

      std::cout << std::endl;
    } else if (command.at(0) == 'i') {
      int k = 0;

      std::cin >> k;

      root = insertNode(root, k);
    }
  }

  return 0;
}

