struct BSTNode
{
	int key;
	BSTNode *lchild, *rchild, *parent;
	BSTNode(int k = 0, BSTNode* p = nullptr, BSTNode* l = nullptr, BSTNode* r = nullptr)
		:key(k), parent(p), lchild(l), rchild(r){}
};
typedef BSTNode* BSTree;
BSTree insert(BSTree& Root, int key)
{
	BSTree parent = nullptr, child = Root;

	while (child != nullptr)
	{
		parent = child;
		if (key > child->key)
			child = child->rchild;
		else
			child = child->lchild;
	}
	child = new BSTNode(key, parent);
	if (parent == nullptr)
		Root = child;
	else if (key > parent->key)
		parent->rchild = child;
	else
		parent->lchild = child;
	return child;
}

void pre_order(const BSTree T)
{
	if (!T)
		return;
	cout << ' ' << T->key;
	pre_order(T->lchild);
	pre_order(T->rchild);
}

void in_order(const BSTree T)
{
	if (!T)
		return;

	in_order(T->lchild);
	cout << ' ' << T->key;
	in_order(T->rchild);
}
