class Node {
public:
    Node(int key, Node* parent = nullptr) : key_(key), parent_(parent), leftChild_(nullptr), rightChild_(nullptr) {}
    void insert(int key) {
        Node* y = nullptr;  // x の親
        Node* x = this;
        while (x != nullptr) {
            y = x;  // 親を設定
            if (key < x->key_) {
                x = x->leftChild_;  // 左の子へ移動
            }
            else {
                x = x->rightChild_; // 右の子へ移動
            }
        }
        Node* z = new Node(key, this);
        if (key < y->key_) {
            y->leftChild_ = z;
        }
        else {
            y->rightChild_ = z;
        }
    }
    void printInorder() {
        if (leftChild_ != nullptr) {
            leftChild_->printInorder();
        }
        cout << " " << key_;
        if (rightChild_ != nullptr) {
            rightChild_->printInorder();
        }
    }
    void printPreorder() {
        cout << " " << key_;
        if (leftChild_ != nullptr) {
            leftChild_->printPreorder();
        }
        if (rightChild_ != nullptr) {
            rightChild_->printPreorder();
        }
    }
private:
    int key_;
    Node* parent_;
    Node* leftChild_;
    Node* rightChild_;
};

class Tree {
public:
    Tree() : root_(nullptr) {}
    void insert(int key) {
        if (root_ != nullptr) {
            root_->insert(key);
        }
        else {
            root_ = new Node(key);
        }
    }
    void print() {
        if (root_ != nullptr) {
            root_->printInorder();
            cout << endl;
            root_->printPreorder();
            cout << endl;
        }
    }
private:
    Node* root_;
};

