int now=0;
void push(int n,int t){
    if(now==0){
        bt[0].n=n;
        now++;
        return;
    }
    if(bt[t].n<n){
        if(bt[t].r==0){
            bt[t].r=now;
            bt[bt[t].r].n=n;
            now++;
        }
        else push(n,bt[t].r);
    }
    if(bt[t].n>n){
        if(bt[t].l==0){
            bt[t].l=now;
            bt[bt[t].l].n=n;
            now++;
        }
        else push(n,bt[t].l);
    }
}
