struct Node{
    int key;
    Node *lch,*rch;  
    Node(int key):key(key),lch(nullptr),rch(nullptr){}
};

class BinarySearchTree
{
 private:
    Node* root;
 public:
    BinarySearchTree():root(nullptr){}
    void insert(int key){
        Node* node=new Node(key);
        if(root==nullptr){
            root=node; return;
        }
        Node *cur=root,*pre=nullptr;
        while(cur!=nullptr){
            pre=cur;
            cur=(node->key<cur->key? cur->lch:cur->rch);
        }
        assert(pre!=nullptr);
        (node->key<pre->key? pre->lch:pre->rch)=node;

    }
    Node* find(int key){
        Node* cur=root;
        while(cur!=nullptr and key!=cur->key){
            cur=(key<cur->key? cur->lch:cur->rch);
        }
        return cur;
    }
    void print(){
        assert(root!=nullptr);
        inorder(root); puts("");
        preorder(root); puts("");
    }
    void inorder(Node* node){
        if(node->lch!=nullptr) inorder(node->lch);
        printf(" %d",node->key);
        if(node->rch!=nullptr) inorder(node->rch);
    }
    void preorder(Node* node){
        printf(" %d",node->key);
        if(node->lch!=nullptr) preorder(node->lch);
        if(node->rch!=nullptr) preorder(node->rch);
    }
};

