    Node *tmp = new Node;
    tmp->key = key;
    tmp->parent = NULL;
    tmp->left = NULL;
    tmp->right = NULL;
    return tmp;
}

Node* root(Node *node) {
    if (!node->parent) return node;
    else return root(node->parent);
}

void insert(Node *node, int key) {
    Node* now = root(node);
