    Node* z = newNode(key);

    // nodeの根から順に辿る
    while (now) {
        par = now;
        if (z->key < now->key) {
            now = now->left;  // 左の子へ移動
        } else {
            now = now->right; // 右の子へ移動
        }
    }
    z->parent = par;

    if (!par) {
        node = z;
    } else if (z->key < par->key) {
        par->left = z;
    } else {
        par->right = z;
    }
}

