class Node {
    public:
        int value;
        Node* left;
        Node* right;
        Node* parent;
        Node(int);
        void join_left(Node* node);
        void join_right(Node* node);
};

Node::Node(int num)
{
    this->value = num;
    this->left = nullptr;
    this->right = nullptr;
    this->parent = nullptr;
}

void Node::join_left(Node* node)
{
    this->left = node;
    node->parent = this;
}

void Node::join_right(Node* node)
{
    this->right = node;
    node->parent = this;
}

void add_node(Node* root, Node* new_node)
{
    Node* current_node = root;
    Node* prev_node = nullptr;
    while(current_node != nullptr) {
        prev_node = current_node;
        if(current_node->value < new_node->value) {
            current_node = current_node->right;
        } else {
            current_node = current_node->left;
        }
    }
    if(prev_node->value < new_node->value) {
        prev_node->join_right(new_node);
    } else {
        prev_node->join_left(new_node);
    }
}

void print_preorder(std::list<Node>& data, Node* node)
{
    if(node == nullptr) {
        return;
    }
    printf(" %d", node->value);
    print_preorder(data, node->left);
    print_preorder(data, node->right);
}

void print_inorder(std::list<Node>& data, Node* node)
{
    if(node == nullptr) {
        return;
    }
    print_inorder(data, node->left);
    printf(" %d", node->value);
    print_inorder(data, node->right);
}

int main()
{
    char buffer[32];
    int size_of_input;
    scanf("%d", &size_of_input);
    std::list<Node> data;
    for(int i = 0; i < size_of_input; i++) {
        scanf("%32s", buffer);
        if(strcmp(buffer, "insert") == 0) {
            int value;
            scanf("%d", &value);
            if(data.empty()) {
                data.push_back(Node(value));
                continue;
            }
            data.push_back(Node(value));
            add_node(&data.front(), &data.back());
        } else if(strcmp(buffer, "print") == 0) {
            print_inorder(data, &data.front());
            putchar('\n');
            print_preorder(data, &data.front());
            putchar('\n');
        } else {
            fputs("Invalid command.\n", stderr);
            exit(EXIT_FAILURE);
        }
    }
    return EXIT_SUCCESS;
}

