void ins(int num){
  Node *n_node;
  n_node=(Node*)malloc(sizeof(Node));
  n_node->key=num;
  n_node->l=NULL;
  n_node->r=NULL;
  Node *x=root;
  Node *y=NULL;
  while(x!=NULL){
    y=x;
    if(x->key < num) x=x->r;
    else x=x->l;
  }
  n_node->p=y;
  if(y==NULL) root = n_node;
  else{
    if(num > y->key) y->r = n_node;
    else y->l = n_node;
  }
}

void array_generator(Node *d){
  if(d==NULL) return;
  if(d->r != NULL){
    num_array.pb(d->r->key);
    array_generator(d->r);
  }
  if(d->l != NULL){
    num_array.pb(d->l->key);
    array_generator(d->l);
  }
}

void del(Node *d){
  array_generator(d);
  if(d->p->l->key == d->key) d->p->l = NULL;
  else d->p->r = NULL;
  free(d);
  rep(i,num_array.size()) ins(num_array[i]);
  num_array.clear();
}

