node * tree::find(int x)
{
	node * p=root;
	while(p!=nullptr){
		if(p->data==x)
			return p;
		else if(x<p->data)
			p=p->l;
		else
			p=p->r;
	}
	return 0;
}
node * tree::findParent(int x)
{
	node * p=root;
	if(p->data==x) return 0;
	while(p!=nullptr){
		if(p->l->data==x||p->r->data==x)
			return p;
		else if(x<p->data)
			p=p->l;
		else
			p=p->r;
	}
	return 0;
}
void tree::Delete(int x)
{
	node * p=find(x);
	if(p==nullptr) return;
	node * q=findParent(x);
	if(q==nullptr){
		if(p->r!=nullptr){
			root=p->r;
			node * t=p->r;
			while(t->l!=nullptr) t=t->l;
			t->l=p->l;
			delete p;
			return;
		}
		else {
			root=p->l;
			delete p;
			return;
		}
	}
	if(p->l==nullptr||p->r==nullptr){
		if(p->l==nullptr&&p->r==nullptr){
			if(q->l==p){q->l=nullptr;delete p;return ;}
			else{q->r=nullptr;delete p;return ;}
			}
		else if(p->l!=nullptr){
			if(q->l==p){q->l=p->l;delete p;return;}
			else{q->r=p->l;delete p;return ;}
		}
		else{
			if(q->l==p){q->l=p->r;delete p;return;}
			else{q->r=p->r;delete p;return;}
		}
	}
	else{
		if(q->l==p){
			node * t=p->l;
			while(t->r!=nullptr) t=t->r;
			q->l=t;
			t->r=p->r;
			delete p;
			return ;
		}
		else{
			node * t=p->r;
			while(t->l!=nullptr) t=t->l;
			q->r=t;
			t->l=p->l;
			delete p;
			return;
		}
	}
}

