// 二分探索木の挿入関数
void insert(Node *new_Element)
{
    Node *tree, *parent;

    // 追加する要素の親
    parent = NULL;
    // 木の先頭アドレス
    tree = Tree;

    while( tree != NULL )
    {
    	parent = tree;

        if( new_Element->key < tree->key )
        {
            // 左の子へ移動
        	tree = tree->left;
        }
        else
        {
            // 右の子へ移動
        	tree = tree->right;
        }
    }

    // 追加する要素の親を設定
    new_Element->parent = parent;

    if( parent == NULL )
    {
        // 木が空の時
    	new_Element->parent = NULL;
        // 木が空のなので, 実体を入れる
        Tree = new_Element;

    }
    else if( new_Element->key < parent->key )
    {
        // 左の子にする
    	parent->left = new_Element;
    }
    else
    {
        // 右の子にする
    	parent->right = new_Element;
    }

    return;
}

// 先行順巡回
// 根節点、左部分木、右部分木の順で節点を巡回
void preorderTreeWalk(Node *Tree)
{
    if( Tree == NULL )
    {
    	return;
    }

    printf(" %d", Tree->key);
    preorderTreeWalk(Tree->left);
    preorderTreeWalk(Tree->right);

    return;
}

