    cout << " " << (u->key);
    preorder(u->left);
    preorder(u->right);
}

void freedive(Node *u)
{
    if (u == NULL) return;
    if (u->left != NULL) freedive(u->left);
    if (u->right != NULL) freedive(u->right);
    free(u);
}

