class BNode{
public:
	int value;
	BNode *right;
	BNode *left;
};

class BTree{
	BNode *root = NULL;
public:
	void Insert(int v){
		BNode *cur = root;
		BNode *prt = NULL;
		BNode *node = new BNode();
		node->value = v;

		while(cur){
			prt = cur;
			if(cur->value < v){
				cur = cur->right;
			}else{
				cur = cur->left;
			}
		}
		if(prt){
			if(prt->value > v){
				prt->left = node;
			}else{
				prt->right = node;
			}
		}
		if(!root){
			root = node;
		}
	}

	void Inorder(BNode *cur, int *cnt){
		if(cur){
			Inorder(cur->left,cnt);
			cout << (*cnt?" ":"") << cur->value;
			++(*cnt);
			Inorder(cur->right,cnt);
		}
	}
	void PrintInorder(){
		int cnt=0;
		Inorder(root,&cnt);
	}
	void Preorder(BNode *cur, int *cnt){
		if(cur){
			cout << (*cnt?" ":"") << cur->value;
			++(*cnt);
			Preorder(cur->left,cnt);
			Preorder(cur->right,cnt);
		}
	}
	void PrintPreorder(){
		int cnt=0;
		Preorder(root,&cnt);
	}
};

