  Node *y = 0;
  Node *x = root;
  while(x != 0){
   y = x;
   if(z->key < x->key){
    x = x->left;
   }else{
    x = x->right;
   }
  }
  z->parent = y;
  if( y == 0){
   root = z;
  }else if(z->key < y->key){
   y->left = z;
  }else{
   y->right = z;
  }
 } 

 void mainoutput(Tree tree){
  outputInorder(tree);
  outputPreorder(tree);
 }

 void outputPreorder(Tree tree){
  stack<Node*> pre;
  pre.push(tree.root);
  while(!pre.empty()){
   Node *buf = pre.top(); pre.pop();
   cout <<" "<< buf->key;
   if(buf->right != 0) pre.push(buf->right);
   if(buf->left != 0) pre.push(buf->left);
  }
  cout << '\n';
 }

 void outputInorder(Tree tree){

  if(tree.root == 0) return ;

  Node* cur = tree.root;
  Node* prev = cur->parent;
  while(cur != 0){
   if(cur->parent == prev){

    //Preorder
    //cout << " " << cur->key;

    if(cur->left != 0){
     prev = cur;
     cur = cur->left;
     continue;
    }else{
     prev = cur->left;
    }
   }

   if(prev == cur->left){
    //inorder
    cout << " " << cur->key;

    if(cur->right != 0){
     prev = cur;
     cur = cur->right;
     continue;
    }else{
     prev = cur->right;
    }
   }

   if(prev == cur->right){
    //postorder
    //cout << " " << cur->key;

    prev = cur;
    cur = cur->parent;
   }
  }
 cout << endl;
 }
};

