    Node *x = head;
    Node *y = NIL;  //表示父节点
    while (x != NIL){
        y = x;
        if (value < x->value){
            x = x->left;
        }
        else{
            x = x->right;
        }
    }
    Node *z = new(Node);
    z->value = value;
    z->left = NIL;
    z->right = NIL;
    if (y != NIL){
        if (z->value < y->value){
            y->left = z;
        }
        else{
            y->right = z;
        }
        z->parent = y;
    } else{
        head = z;
    }
}

