	int x = *root, y = NIL;
	while(x != NIL){
		y = x;
		if(T[i].key < T[x].key)
			x = T[x].left;
		else
			x = T[x].right;
	}
	T[i].parent = y;

	if(y == NIL)
		*root = i;
	else if(T[i].key < T[y].key)
		T[y].left = i;
	else
		T[y].right = i;
}

