    std::vector< int > pre;
    std::vector< int > mid;
    auto dfs = [&](auto&& dfs, node_type * now) -> void {
      pre.emplace_back(now->value);
      if (now->left) dfs(dfs, now->left);
      mid.emplace_back(now->value);
      if (now->right) dfs(dfs, now->right);
    };
    dfs(dfs, top);
