struct Node{
    int num;
    struct Node* left;
    struct Node* right;
};

struct Node* root;

void insert(int num, struct Node* n){
    if(root == NULL){
        root = (Node*) malloc(sizeof(struct Node));
        root->num = num;
        root->left = NULL;
        root->right = NULL;
        return;
    }

    if(num < n->num){
        if(n->left == NULL){
            n->left = (Node*) malloc(sizeof(struct Node));
            n->left->num = num;
            n->left->left = NULL;
            n->left->right = NULL;
        }else{
            insert(num, n->left);
        }
    }else{
        if(n->right == NULL){
            n->right = (Node*) malloc(sizeof(struct Node));
            n->right->num = num;
            n->right->left = NULL;
            n->right->right = NULL;
        }else{
            insert(num, n->right);
        }
    }
}

void print_middle(struct Node* n){
    if(n == NULL){
        return;
    }
    print_middle(n->left);
    printf(" %d", n->num);
    print_middle(n->right);
}

void print_before(struct Node* n){
    if(n == NULL){
        return;
    }
    printf(" %d", n->num);
    print_before(n->left);
    print_before(n->right);
}

