template<class T>
class BinaryTree{
private:
    struct Node{
        T val;
        Node *par;
        Node *left;
        Node *right;
    };
    Node *root;
    void insert(int x,Node* now){
        if(x < now->val){
            if(now->left != nullptr){
                insert(x,now->left);
            }else{
                now->left = new Node;
                now->left->val = x;
                now->left->left = nullptr;
                now->left->right = nullptr;
            }
        }else{
            if(now->right != nullptr){
                insert(x,now->right);
            }else{
                now->right = new Node;
                now->right->val = x;
                now->right->left = nullptr;
                now->right->right = nullptr;
            }
        }
    }
    void inorder_walk(Node* now,vec<T>& v){
        if(now->left!=nullptr) inorder_walk(now->left,v);
        v.push_back(now->val);
        if(now->right!=nullptr) inorder_walk(now->right,v);
    }
    void preorder_walk(Node* now,vec<T>& v){
        v.push_back(now->val);
        if(now->left!=nullptr) preorder_walk(now->left,v);
        if(now->right!=nullptr) preorder_walk(now->right,v);
    }
public:
    BinaryTree():root(nullptr){}
    void insert(T x){
        if(root==nullptr){
            root = new Node;
            root->val = x;
            root->left = nullptr;
            root->right = nullptr;
        }else{
            insert(x,root);
        }
    }

    vec<T> inorder_walk(){
        vec<T> res;
        inorder_walk(root,res);
        return res;
    }
    vec<T> preorder_walk(){
        vec<T> res;
        preorder_walk(root,res);
        return res;
    }
};

