int id = 0;       // new node id (=node count in the tree)
int P[NMAX + 10]; // parent
int L[NMAX + 10]; // left child
int R[NMAX + 10]; // right child
int V[NMAX + 10]; // value

void insert(int val) {
    V[id] = val;
    L[id] = NIL;
    R[id] = NIL;
    // all below is to set P[id], L[P[id]], R[P[id]]

    if (root == NIL) {
        P[id] = NIL;
        root = id;
        id++;
        return;
    }
    int c = root;
    int parent = NIL; // parent = P[id]
    // find P[id]
    while (c != NIL) {
        parent = c;
        if (val <= V[c])
            c = L[c];
        else
            c = R[c];
    }
    P[id] = parent;
    // update L[parent] or R[parent]
    if (V[id] <= V[parent])
        L[parent] = id;
    else
        R[parent] = id;
    id++;
}

