		Node *cur = st.top();
		st.pop();
		if (cur != NIL) {
			cur->visited = false;
			st.push(cur->left);
			st.push(cur->right);
		}
	}
}

void inOrder() {
	resetVisitedFlag();
	stack<Node*> st;
	st.push(root);
	while (st.size() != 0) {
		Node* cur = st.top()->left;
		while (cur != NIL && !cur->visited) {
			st.push(cur);
			cur = cur->left;
		}
		cur = st.top();
		st.pop();
		cout << " " << cur->key;
		cur->visited = true;
		Node *right = cur->right;
		if (right != NIL && !right->visited) {
			st.push(right);
		}
	}
	cout << endl;
}

void preOrder() {
	stack<Node*> st;
	st.push(root);
	while (st.size() != 0) {
		Node *cur = st.top();
		st.pop();
		if (cur != NIL) {
			cout << " " << cur->key;
			st.push(cur->right);
			st.push(cur->left);
		}
	}
	cout << endl;
}

