int insert(Tree *nodes, int n, int root) {
    int y = -1;
    int x = root;
    while (x != -1) {
        y = x;
        if (nodes[n].key < nodes[x].key) {
            x = nodes[x].left;
        }
        else {
            x = nodes[x].right;
        }
    }
    nodes[n].parent = y;
    if (y == -1) {
        root = n;
    }
    else if (nodes[n].key < nodes[y].key) {
        nodes[y].left = n;
    }
    else {
        nodes[y].right = n;
    }
    return root;
}


