void insert(Node *parent, int key) {
    if(root == nullptr) {
        root = new Node(key);
        return;
    }
    if(key <= parent->key) {
        if(parent->left == nullptr) {
            parent->left = new Node(key);
            return;
        }
        insert(parent->left, key);
    } else {
        if (parent->right == nullptr)
        {
            parent->right = new Node(key);
