struct Node {
  int val;
  Node *left;
  Node *right;

  Node(int val) : val(val), left(NULL), right(NULL) {};
};

Node *insert(Node *node, int val) {
  if (node == NULL) {
    return new Node(val);
  }

  if (val < node->val) {
    node->left = insert(node->left, val);
  } else {
    node->right = insert(node->right, val);
  }

  return node;
}

void generatePreorder(Node *node, vector<int> &vec) {
  vec.push_back(node->val);
  if (node->left) {
    generatePreorder(node->left, vec);
  }
  if (node->right) {
    generatePreorder(node->right, vec);
  }
}

void generateInorder(Node *node, vector<int> &vec) {
  if (node->left) {
    generateInorder(node->left, vec);
  }
  vec.push_back(node->val);
  if (node->right) {
    generateInorder(node->right, vec);
  }
}

void printVec(vector<int> &vec) {
  for (auto it = vec.begin(); it != vec.end(); ++it) {
    cout << " " << *it;
  }
  cout << endl;
}

void print(Node *root) {
  vector<int> inorder;
  generateInorder(root, inorder);
  printVec(inorder);

  vector<int> preorder;
  generatePreorder(root, preorder);
  printVec(preorder);
}

