void insert(tree *t, int id){
	node *x, *y, *n;
	n = new node;
	n->key = id;
	n->left = t->nil;
	n->right = t->nil;
	x = t->root;
	while(x != t->nil){
		y = x;
		if(id > x->key){
			x = x->right;
		}
		else{
			x = x->left;
		}
	}
	if(id > y->key){
		y->right = n;
	}
	else{
		y->left = n;
	}
}


