            for (int j = 0; j < mcount; j++) cout << " " << middlePrintT[j];
            cout << "\n";
            for (int j = 0; j < fcount; j++) cout << " " << firstPrintT[j];
            cout << "\n";
        }
    }

    return 0;
}

