Node *NIL, *root;

void insert(int key) {
    Node *x, *y, *z;

    // initialize
    z = new Node;  // 新しい要素のメモリ確保
    z->key = key;
    z->left = NIL;
    z->right = NIL;
    y = NIL;
    x = root;

    // rootから適切な位置まで二分木をたどる
    while (x != NIL) {
        y = x;
        if (z->key < x->key) x = x->left;
        else x = x->right;
    }

    // 新しい要素を配置する場所を決定
    z->parent = y;  
    if (y == NIL) root = z;  // もともと木が存在しなかった場合
    else if (z->key < y->key) y->left = z;
    else y->right = z;    
}

