node *NIL,*root;

void insert(int v)
{
	node *y=NIL,*x=root,*z=new node;
	z->key=v;z->l=z->r=NIL;
	while(x!=NIL)
	{
		y=x;
		if(z->key<x->key)x=x->l;
		else x=x->r;
	}
	z->p=y;
	if(y==NIL)root=z;
	else if(z->key<y->key)y->l=z;
	else y->r=z;
	return;
}

node* find(int k)
{
	node *x=root;
	while(x!=NIL&&k!=x->key)
	{
		if(k<x->key)x=x->l;
		else x=x->r;
	}
	return x;
}

node* next(node *z)
{
	node *x,*y;
	if(z->r!=NIL)
	{
		x=z->r;
		while(x->l!=NIL)x=x->l;
		return x;
	}

	y=z->p;
	while(y!=NIL&&x==y->r)
	{
		x=y;
		y=y->p;
	}
	return y;
}

void del(node *z)
{
	node *y,*x;
	if(z->l==NIL||z->r==NIL)y=z;
	else y=next(z);

	if(y->l!=NIL)x=y->l;
	else x=y->r;

	if(x!=NIL)x->p=y->p;

	if(y->p==NIL)root=x;
	else if(y==y->p->l)y->p->l=x;
	else y->p->r=x;

	if(y!=z)z->key=y->key;
	delete(y);
	return;
}

