struct bst
{
#define VNI vector<node>::iterator
	struct node {
		int v;
		VNI l = VNI(), r = VNI();
	};
	typedef vector<node> vn;
	typedef vn::iterator vni;
	vn nodes;
	vni root = vni(), i, vnin = root;

	bst(int n)
	{
		nodes.resize(n);
		i = nodes.begin();
	}

	vni insert (vni r, int n)
	{
		if (r == vnin) {
			(*i).v = n;
			r = i++;
		} else if ((*r).v < n)
			(*r).r = insert((*r).r, n);
		else
			(*r).l = insert((*r).l, n);
		return r;
	}
	void insert (int n)
	{
		root = insert(root, n);
