		if (NODE->right == 0 && NODE->left == 0) { delete NODE; }
		else
		{
			if (NODE->right != 0)
			{
				Delete(NODE->right);
			}
			if (NODE->left != 0)
			{
				Delete(NODE->left);
			}
			delete NODE;
		}
	}
	Node* CreateNode(int KEY, Node* PARENT) 
	{ 	
		Node* temp= new Node(KEY, PARENT);
		return temp;
	}
	void Insert(int KEY, Node* NODE)
	{
		if (NODE->key < KEY)
		{
			if (NODE->right == 0)
			{
				Node* temp=CreateNode(KEY, NODE);
				NODE->right = temp;
				temp->parent = NODE;
			}
			else Insert(KEY, NODE->right);
		}
		else
		{
			if (NODE->left == 0)
			{
				Node* temp = CreateNode(KEY, NODE);
				NODE->left = temp;
				temp->parent = NODE;
			}
			else Insert(KEY, NODE->left);
		}
	}
	Node* nodes_root;
	void ShowPreoder(Node* NODE)
	{
		printf(" %d", NODE->key);
		if (NODE->left != 0) ShowPreoder(NODE->left);
		if (NODE->right != 0) ShowPreoder(NODE->right);
	}
	void ShowInoder(Node* NODE)
	{
		if (NODE->left != 0) ShowInoder(NODE->left);
		printf(" %d", NODE->key);
		if (NODE->right != 0) ShowInoder(NODE->right);
	}
	void ShowPostoder(Node* NODE)
	{
		if (NODE->left != 0) ShowPostoder(NODE->left);
		if (NODE->right != 0) ShowPostoder(NODE->right);
		printf(" %d", NODE->key);
	}

};

