	Node *cur = Tree;
	Node *parent = NULL;
	while (cur != NULL) {
		parent = cur;
		if (key < cur->val) {
			cur = cur->left;
		} else {
			cur = cur->right;
		}
	}
	if (parent == NULL) {
		Tree = new Node;
		Tree->val = key;
		return;
	}
	Node *t = new Node;
