#include <iostream>
using namespace std;

const int NIL = -1;

struct Node{
    int key;
    Node *left, *right;
    Node(int v = NIL) : key(v) {
        left = right = nullptr;
    }
};

void insert(Node* node, int key)
{
    if(node->key > key){
        if(node->left)
        {
            insert(node->left, key);
        }
        else{
            Node* newnode = new Node(key);
            node->left = newnode;
        }
    }
    else if(node->key < key){
        if(node->right){
            insert(node->right, key);
        }
        else{
            Node* newnode = new Node(key);
            node->right = newnode;
        }
    }
}

struct PrintTree
{
    void preorder(Node* node)
    {
        if(node){
            cout << " " << node->key;
            preorder(node->left);
            preorder(node->right);
        }
    }

    void inorder(Node* node)
    {
        if(node){
            inorder(node->left);
            cout << " " << node->key;
            inorder(node->right);
        }
    }

    void printTree(Node* root)
    {
        // inorder
        inorder(root);
        cout << endl;
        // preorder
        preorder(root);
        cout << endl;
    }
};

int main()
{
    int n, key;
    char command[10];
    Node* root = nullptr;
    PrintTree print;
    cin >> n;
    for(int i=0;i<n;++i)
    {
        cin >> command;
        if(command[0] == 'i')
        {
            if(root){
                cin >> key;
                insert(root, key);
            }
            else{
                cin >> key;
                root = new Node(key);
            }
        }
        else{
            print.printTree(root);
        }
    }
}

