struct Node {
    int left = -1, right = -1;
    int number;
};

struct BTree {
    public:
        std::vector<Node> nodes;
        void insert(int q) {
            Node nd;
            nd.number = q;
            nodes.push_back(nd);
            if ( nodes.size() > 1 ) {
                add_node(q, 0);
            }
        };
        void inorder(int current) {
            if ( nodes[current].left >= 0 ) {
                inorder(nodes[current].left);
            }
            std::cout << " " << nodes[current].number;
            if ( nodes[current].right >= 0 ) {
                inorder(nodes[current].right);
            }
        };
        void preorder(int current) {
            std::cout << " " << nodes[current].number;
            if ( nodes[current].left >= 0 ) {
                preorder(nodes[current].left);
            }
            if ( nodes[current].right >= 0 ) {
                preorder(nodes[current].right);
            }
        };
    private:
        void add_node(int q, int current) {
            if ( q > nodes[current].number ) {
                if ( nodes[current].right >= 0) {
                    add_node(q, nodes[current].right);
                } else {
                    nodes[current].right = nodes.size() - 1;
                }
            } else {
                if ( nodes[current].left >= 0) {
                    add_node(q, nodes[current].left);
                } else {
                    nodes[current].left = nodes.size() - 1;
                }
            }
        }
};

