struct binaryTree {
	int key;
	int left;
	int right;
	int parent;
};

void insert(vector<struct binaryTree> &T, int key){	
	if(T.size() == 0){
		binaryTree x = {key, -1, -1, -1};
		T.push_back(x);
	}else{
		int y = 0;
		bool flag = true;
		while(flag){
			if(T[y].key > key){
				if(T[y].left == -1){
					T[y].left = T.size();
					binaryTree x = {key, -1, -1, y};
					T.push_back(x);
					flag = false;
				}else{
					y = T[y].left;
				}
			}else{
				if(T[y].right == -1){
					T[y].right = T.size();
					binaryTree x = {key, -1, -1, y};
					T.push_back(x);
					flag = false;
				}else{
					y = T[y].right;
				}
			}
		}
	}
}

void Preorder(vector<struct binaryTree> T, int x){
	cout<<" "<<T[x].key;

	if(T[x].left != -1)
		Preorder(T, T[x].left);

	if(T[x].right != -1)
		Preorder(T, T[x].right);
}

void Inorder(vector<struct binaryTree> T, int x){
	if(T[x].left != -1)
		Inorder(T, T[x].left);

	cout<<" "<<T[x].key;

	if(T[x].right != -1)
		Inorder(T, T[x].right);
}

