struct node{
    node *left;
    node *right;
    int key;
};

struct tree{
    node *nil;
    node *root;
};

void insert(tree *t, int id){
    node *x, *y, *n;
    n = new node;
    n->key = id;
    n->left = t->nil;
    n->right = t->nil;
    x = t->root;
    while(x != t->nil){
        y = x;
        if(id > x->key){
            x = x->right;
        }
        else{
            x = x->left;
        }
    }
    if(id > y->key){
        y->right = n;
    }
    else{
        y->left = n;
    }
}


void printIn(tree *t, node *n){
    if (n == t->nil){
        return ;
    }
    else{
        printIn(t, n->left);
        printf(" %d", n->key);
        printIn(t, n->right);
    }
}

void printPre(tree *t, node *n){
    if (n == t->nil){
        return ;
    }
    else{
        printf(" %d", n->key);
        printPre(t, n->left);
        printPre(t, n->right);
    }
}

