struct Node {
  int value;
  Node *rightNode, *leftNode;

  Node(int value): value(value) {
    rightNode = nullptr;
    leftNode=  nullptr;
  }

  bool rightEmpty() {
    return rightNode == nullptr;
  }

  bool leftEmpty() {
    return leftNode == nullptr;
  }

  void attachNodeToLeft(Node* node) {
    leftNode = node;
  }

  void attachNodeToRight(Node* node) {
    rightNode = node;
  }

};

class Tree {
private:
  Node* rootNode;
public:
  void setRoot(Node *rootNode){
    this->rootNode = rootNode;
  }

  void addNode(Node *newNode) {
    Node* comparingNode = rootNode;
    while(1) {
      if(comparingNode->value > newNode->value) {
        if(comparingNode->leftEmpty()) {
          comparingNode->attachNodeToLeft(newNode);
          break;
        }else {
          comparingNode = comparingNode->leftNode;
        }
      }else {
        if(comparingNode->rightEmpty()) {
          comparingNode->attachNodeToRight(newNode);
          break;
        }else {
          comparingNode = comparingNode->rightNode;
        }
      }
    }
  }

  std::vector<int> inOrder(Node* targetNode) {
    std::vector<int> ret;
    if(!targetNode->leftEmpty()) {
      std::vector<int> left = inOrder(targetNode->leftNode);
      ret.insert(ret.end(), left.begin(), left.end());
    }
    ret.push_back(targetNode->value);
    if(!targetNode->rightEmpty()) {
      std::vector<int> right = inOrder(targetNode->rightNode);
      ret.insert(ret.end(), right.begin(), right.end());
    }
    return ret;
  }

  std::vector<int> preOrder(Node* targetNode) {
    std::vector<int> ret;
    ret.push_back(targetNode->value);

    if(!targetNode->leftEmpty()) {
      std::vector<int> left = preOrder(targetNode->leftNode);
      ret.insert(ret.end(), left.begin(), left.end());
    }
    if(!targetNode->rightEmpty()) {
      std::vector<int> right = preOrder(targetNode->rightNode);
      ret.insert(ret.end(), right.begin(), right.end());
    }
    return ret;
  }

