struct Node {
  ll value;
  Node *left = nullptr,
       *right = nullptr,
       *parent = nullptr;

  Node(ll value = -1): value(value) {}
};

class BST {
  Node *root = nullptr;

  string tos_pre(Node *nd) {
    string s = "";

    s += " " + to_string(nd->value);
    if (nd->left) s += tos_pre(nd->left);
    if (nd->right) s += tos_pre(nd->right);

    return s;
  }

  string tos_in(Node *nd) {
    string s = "";

    if (nd->left) s += tos_in(nd->left);
    s += " " + to_string(nd->value);
    if (nd->right) s += tos_in(nd->right);

    return s;
  }

public:
  void insert(ll value) {
    Node *x = root, *y = nullptr, *z = new Node(value);

    while (x) {
      y = x;
      x = z->value < x->value ? x->left : x->right;
    }
    z->parent = y;

    if (!y) root = z;
    else if (z->value < y->value) y->left = z;
    else y->right = z;
  }

  string print_pre() {
    return tos_pre(root);
  }

  string print_in() {
    return tos_in(root);
  }
};

