class Tree
{
    Node *root;

    public:
    Tree()
    {
        root = NULL;
    }

    void insert(int key)
    {
        Node *node = new Node(key);

        if (root == NULL)
        {
            root = node;
            return;
        }

        Node *target = root;

        while(target != NULL)
        {
            if (node->key < target->key)
            {
                if (target->left == NULL)
                {
                    target->left = node;
                    node->parent = target;
                    target = NULL;
                }else
                {
                    target = target->left;
                }
            }
            else
            {
                if (target->right == NULL)
                {
                    target->right = node;
                    node->parent = target;
                    target = NULL;
                }else
                {
                    target = target->right;
                }            
            }            
        }
    }

