{
    NodeA *next = head;
    NodeA *prev = NULL;
    bool isLeft = true;
    while (next != NULL)
    {
        prev = next;
        if ((*next).key >= key)
        {
            next = (*next).left;
            isLeft = true;
        }
        else if ((*next).key <= key)
        {
            next = (*next).right;
            isLeft = false;
        }
    }
    if (prev == NULL)
    {
        head = (NodeA *)malloc(sizeof(NodeA));
        (*head).key = key;
        (*head).left = NULL;
        (*head).right = NULL;
        return;
    }
    if (isLeft)
    {
        (*prev).left = (NodeA *)malloc(sizeof(NodeA));
        (*(*prev).left).key = key;
        (*(*prev).left).left = NULL;
        (*(*prev).left).right = NULL;
    }
    else
    {
        (*prev).right = (NodeA *)malloc(sizeof(NodeA));
        (*(*prev).right).key = key;
        (*(*prev).right).left = NULL;
        (*(*prev).right).right = NULL;
    }

}
