typedef struct node
{
	int x;
	int isRoot;
	int mostLeft;
	struct node *left,*right;
}node;

node *newNode(int x, int isRoot)
{
	node *tmp = (node *)malloc(sizeof(node));
	tmp->left=NULL;
	tmp->right=NULL;
	tmp->x=x;
	tmp->isRoot=isRoot;
	tmp->mostLeft=0;
	//prd(sizeof(tmp));
	return tmp;
}

node *insert(node *root,int x,int isRoot)
{
	//prd(x);
	if(root==NULL)
	return newNode(x,isRoot);

	if(x<=root->x)
	root->left=insert(root->left,x,isRoot);
	if(x>=root->x)
	root->right=insert(root->right,x,isRoot);

	return root;
}	

void toTheMostLeft(node *root)
{
	node *poi=root;
	while(poi!=NULL)
	{
		if(poi->left==NULL)
		{
			poi->mostLeft=1;
			return;
		}
		poi->mostLeft=0;
		poi=poi->left;
	}
}


