int g_pCount = 0;

struct Node {
  Node(int key) :
    key_(key),
    left_(nullptr),
    right_(nullptr) {
      g_pCount++;
      DPRINTF("Allocated. (addr %p  key %d  pCount %d)\n", this, this->key_, g_pCount);
    }
  Node() :
    key_(-1),
    left_(nullptr),
    right_(nullptr) {
      Node(-1);
    }

  ~Node() {
    g_pCount--;
    DPRINTF("Deallocated. (addr %p  key %d  pCount %d)\n", this, this->key_, g_pCount);
  }

  int key_;
  Node *left_;
  Node *right_;
};

void insert(Node **root, Node *n)
{
  if (root == nullptr || n == nullptr)
  {
    assert(false && "nullptr catched\n");
    return;
  }

  if (*root == nullptr)
  {
    *root = n;
    return;
  }

  Node *parent = nullptr;
  Node *child = *root;

  while (child != nullptr)
  {
    parent = child;

    if (n->key_ < child->key_)
      child = child->left_;
    else
      child = child->right_;
  }

  if (n->key_ < parent->key_)
  {
    parent->left_ = n;

    DPRINTF("left - parent->key_ %d  n->key_ %d\n",
        parent->key_, n->key_);
  }
  else
  {
    parent->right_ = n;

    DPRINTF("right - parent->key_ %d  n->key_ %d\n",
        parent->key_, n->key_);
  }

}

void printPreorder(Node *node, bool isRoot = true)
{
  if (node == nullptr)
    return;

  if (!isRoot)
    printf(" ");
  printf("%d", node->key_);

  printPreorder(node->left_, false);
  printPreorder(node->right_, false);

  if (isRoot)
    cout << endl;
}

void printInorder(Node *node, bool isRoot = true)
{
  static bool calledBefore = false;

  if (isRoot)
    calledBefore = false;

  if (node == nullptr)
    return;

  printInorder(node->left_, false);

  if (!calledBefore)
    calledBefore = true;
  else
    printf(" ");

  printf("%d", node->key_);

  printInorder(node->right_, false);

  if (isRoot)
    cout << endl;
}


bool freeNodePointer(Node *root)
{
  if (root == nullptr)
    return false;

  if (freeNodePointer(root->left_))
    delete(root->left_);

  if (freeNodePointer(root->right_))
    delete(root->right_);

  return true;
}

