{
  int numOfOrder;
  cin >> numOfOrder; cin.ignore();

  Node **root = new (Node*);
  *root = nullptr;

  for (int i = 0; i < numOfOrder; i++)
  {
    string order; cin >> order;

    if (order == "insert")
    {
      int key; cin >> key;
      DPRINTF("%s %d\n", order.c_str(), key);

      Node *n = new Node(key);
      insert(root, n);

    }
    else if (order == "print")
    {
      DPRINTF("%s\n", order.c_str());

      printInorder(*root);
      printPreorder(*root);
    }
    else
    {
      // must not be here
      assert(false && "Unknown order");
    }

    cin.ignore();
  }

  freeNodePointer(*root);
  delete(*root);
  delete(root);

  return 0;
}

