    while ( x != NIL ) {   //xがNILにたどり着いた時終了、その時のyがzの親となる
        y = x;   //親の設定(=root)、zの親の候補として1つ前の節点yを保持
        if ( z->key < x->key ) {   //x->keyにはrootの値が保持
            x = x->left;   //左の子へ移動
        } else {
            x = x->right;   //右の子へ移動
        }
    }

    z->parent = y;
    if ( y == NIL ) {   //Tが空の場合、最初に挿入した値を根とする
        root = z;
    } else {
        if ( z->key < y->key ) {
            y->left = z;   //zをyの左の子にする
        } else {
            y->right = z;   //zをyの右の子にする 
        }
    }
}

