vector<string> split(string str, char ch)
{
  int first = 0;
  int last = str.find_first_of(ch);

  if(last == string::npos)
    {
      last = SIZ(str);
    }

  vector<string> result;

  while( first < SIZ(str) )
    {
      string Ssubstr(str, first, last - first);
      result.push_back(Ssubstr);
      first = last + 1;
      last = str.find_first_of(ch, first);

      if(last == string::npos)
	{
	  last = SIZ(str);
	}
    }

  return result;
}



int gcd( int a , int b ) // assuming a,b >= 1
{
  if( a < b )
    {
      return gcd( b , a );

    }

  if( a % b == 0 )
    {
      return b;

    }

  return gcd( b , a % b );

}

int lcm( int a , int b ) // assuming a,b >= 1
{
  return  a * b / gcd( a , b );

}

lli pow_fast( lli x, lli n_power , lli modulus )
{

  if( n_power == 0 )
    {
      return 1;
    }

  if( n_power % 2 == 0)
    {
      return pow_fast( x * x % modulus , n_power / 2 , modulus );  
    }


  return x * pow_fast( x , n_power - 1 , modulus ) % modulus;
}


struct UnionFind
{
  vector<int> parent, rank; 

  UnionFind( int size ) : parent( size ), rank( size ) //constructor
  {
    for( int i = 0 ; i < size ; ++ i )
      {
	parent[i] = i;
	rank[i] = 0;
      }
  }

  int root( int x )
  {
    if( parent[x] == x )
      {
	return x;
      }

    return parent[x] = root(parent[x]);
  }

  void unite( int x, int y )
  {
    x = root(x); 
    y = root(y);

    if( x == y )
      {
	return; 
      }

    if( rank[x] < rank[y] )
      {
	parent[x] = y;
      }
    else
      {
	parent[y] = x;

	if( rank[x] == rank[y] )
	  {
	    ++ rank[x];
	  }

      }

  }

  bool sametree( int x, int y )
  {
    return root(x) == root(y);
  }

};



