vector<int>preorder,inorder,postorder;

void rec(int left,int right){
  int root,mid;
  if(left>=right)return;
  root=preorder[pos++];
  mid=distance(inorder.begin(),find(inorder.begin(),inorder.end(),root));
  rec(left,mid);
  rec(mid+1,right);
  postorder.push_back(root);
}

void calc(){
  int i;
  pos=0;
  rec(0,preorder.size());
  for(i=0;i<n;i++){
    if(i>0)printf(" ");
