void insert(vector<struct binaryTree> &T, int key){
	int x = 0, y = NIL;
	if(T.size() != 0){
		while(x != NIL){
			y = x;
			if(key < T[x].key)
				x = T[x].left;
			else
				x = T[x].right;
		}

		if(key < T[y].key)
			T[y].left = T.size();
		else
			T[y].right = T.size();
	}

	binaryTree z = {key, NIL, NIL, y};
	T.push_back(z);
}

