using namespace std;

template <typename T>
struct node_t {
  T key;
  node_t *lc, *rc;
  explicit node_t(T v): key(v), lc(nullptr), rc(nullptr) {}
};

template <typename T>
void insert(node_t<T> *&t, T v) {
  using ptr_t = node_t<T> *;
  ptr_t z = new node_t<T>(v);
  ptr_t y = nullptr;
  ptr_t x = t;
  while (x) {
    y = x;
    if (z->key < x->key) {
      x = x->lc;
    } else {
      x = x->rc;
    }
  }
  if (!y) {
    t = z;
  } else if (z->key < y->key) {
    y->lc = z;
  } else {
    y->rc = z;
  }
}

template <typename T>
void inorder_walk(node_t<T> *t) {
  using ptr_t = node_t<T> *;
  stack<tuple<ptr_t, bool>> stk;
  stk.emplace(t, false);
  while (!stk.empty()) {
    ptr_t ptr; bool op;
    tie(ptr, op) = stk.top(); stk.pop();
    if (!ptr) { continue; }
    if (op) {
      cout << " " << ptr->key;
    } else {
      stk.emplace(ptr->rc, false);
      stk.emplace(ptr, true);
      stk.emplace(ptr->lc, false);
    }
  }
  cout << endl;
}

template <typename T>
void preorder_walk(node_t<T> *t) {
  using ptr_t = node_t<T> *;
  stack<ptr_t> stk;
  stk.push(t);
  while (!stk.empty()) {
    auto const ptr = stk.top(); stk.pop();
    if (!ptr) { continue; }
    cout << " " << ptr->key;
    stk.push(ptr->rc);
    stk.push(ptr->lc);
  }
  cout << endl;
}

