		return;
	}
	~Node(){
		if(l != NULL){ delete l; l = NULL; }
		if(r != NULL){ delete r; r = NULL; }
	}
};

void insert(Node **root_handle, long key){
	Node *y = NULL;
	Node *x = *root_handle;

	while(x != NULL){
		y = x;
		if(key < x->key){
			x = x->l;
		}
		else{
			x = x->r;
		}
	}

	Node *z = new Node;
	z->parent = y;
	z->key = key;

	if(y == NULL){
		*root_handle = z;
	}
	else if(z->key < y->key){
		y->l = z;
	}
	else{
		y->r = z;
	}
	return;
}

