struct Node {
	long long key;
	Node* left;
	Node* right;
};

void inseart(Node** root, Node* data) {
	if (*root == NULL) {
		*root = data;
		return;
	}
	Node* prev = NULL;
	Node* node = *root;
	while (node != NULL) {
		prev = node;
		if (node->key > data->key) {
			node = node->left;
		}
		else {
			node = node->right;
		}
	}
	if (prev->key > data->key) {
		prev->left = data;
	}
	else {
		prev->right = data;
	}
}

void visit(Node* root, vector<int>& pre,vector<int>& ino) {
	pre.push_back(root->key);
	if (root->left != NULL) {
		visit(root->left, pre, ino);
	}
	ino.push_back(root->key);
	if (root->right != NULL) {
		visit(root->right, pre, ino);
	}
}

