Node* NIL;
Node* getNil()
{
    Node* node = (Node*)malloc(sizeof(Node));
    node->index = -1;
    node->parent = node;
    node->left = node;
    node->right = node;
    return node;
}
Node* getNewNode()
{
    Node* node = (Node*)malloc(sizeof(Node));
    node->index = -1;
    node->parent = NIL;
    node->left = NIL;
    node->right = NIL;
    return node;
}
Node* insertNode(Node* rootNode, int index)
{
    Node* node = rootNode;
    Node* parentNode = NIL;
    Node* indexNode = getNewNode();
    indexNode->index = index;
    if (node->index == -1) {
	return indexNode;
    }
    while (node->index != -1) {
	parentNode = node;
	if (node->index > index) {
	    node->left->parent = node;
	    node = node->left;
	} else {
	    node->right->parent = node;
	    node = node->right;
	}
    }
    indexNode->parent = parentNode;
    if (parentNode->index > index) {
	parentNode->left = indexNode;
    } else {
	parentNode->right = indexNode;
    }
    return rootNode;
}
