int binary_tree::delete1(int key){
	tree *p=root, *parent=root, *marker;

	p = find(key);

	marker = p;
	if (p==NULL){}
	else if (p == root){
		if (p->Left == NULL && p->Right == NULL)
			root = NULL;

		else if (p->Left == NULL)
			root = p->Right;

		else if (p->Right == NULL)
			root = p->Left;

		else{
			tree *minp;
			minp = p->Right;
			while (minp->Left != NULL){
				p = minp;
				minp = minp->Left;
			}
			if (minp != p->Right){
				p->Left = minp->Right;
				minp->Right = root->Right;
			}
			minp->Left = root->Left;
			root = minp;
		}
	}else{
		if (p->Left == NULL && p->Right == NULL)
			if (parent->Left == p)
				parent->Left = NULL;
			else
				parent->Right = NULL;
		else if (p->Left == NULL)
			if (parent->Left == p)
				parent->Left = p->Right;
			else
				parent->Right = p->Right;
		else if (p->Right == NULL)
			if (parent->Left == p)
				parent->Left = p->Left;
			else
				parent->Right = p->Left;
		else{
			tree *minp;
			parent = p;
			minp = p->Right;
			while (minp->Left != NULL){
				parent = minp;
				minp = minp->Left;
			}
			if (minp != p->Right){
				p->Left = minp->Right;
				minp->Right = parent->Right;
			}
			minp->Left = parent->Left;
			parent = minp;
		}
		delete marker;
	}
	return 0;
}

