    Node *x = root;

    while (x != nil) {
        y = x;  // 親を設定
        if (z->key < x->key) x = x->l;  // 左の子へ移動
        else x = x->r;  // 右の子へ移動
    }

    z->p = y;

    if (y == nil) root = z;
