typedef struct node
{
    // 節点の値
    int key;
    // 節点の親
    struct node *parent;
    // 節点の左の子
    struct node *left;
    // 節点の右の子
    struct node *right;
}Node;

// グローバル変数の定義
Node *Tree;

void preorderTreeWalk(Node *Tree);
void inorderTreeWalk(Node *Tree);
void postorderTreeWalk(Node *Tree);

// 二分探索木の挿入関数
void insert(Node *new_Element)
{
    Node *tree, *parent;

    parent = NULL;
    tree = Tree;

    while( tree != NULL )
    {
    	parent = tree;

        if( new_Element->key < tree->key )
        {
            // 左の子へ移動
        	tree = tree->left;
        }
        else
        {
            // 右の子へ移動
        	tree = tree->right;
        }
    }

    new_Element->parent = parent;

    if( parent == NULL )
    {
    	new_Element->parent = NULL; // x の親
    	Tree = new_Element;

    }
    else if( new_Element->key < parent->key )
    {
    	parent->left = new_Element; // z を y の左の子にする
    }
    else
    {
    	parent->right = new_Element; // z を y の右の子にする
    }

    return;
}

