	Node(int k, Node *p = NULL, Node *l = NULL, Node *r = NULL) : key(k), parent(p), lchild(l), rchild(r) {}
} *Tree;

void insert(Tree& T,  int k)
{
	Tree p = NULL;
	Tree x = T;
	Tree z;
	while (x != NULL)
	{
		p = x;
		if (x->key > k)
			x = x->lchild;
		else
			x = x->rchild;
	}
	z = new Node(k, p);
	if (p == NULL)
	{
		T = z;
	}
	else if (z->key > p->key)
		p->rchild = z;
	else
		p->lchild = z;
}

void preorder(Tree T)
{
	if (T == NULL)
		return;
	cout << ' ' << T->key;
	preorder(T->lchild);
	preorder(T->rchild);
}

void inorder(Tree T)
{
	if (T == NULL)
		return;
	inorder(T->lchild);
	cout << ' ' << T->key;
	inorder(T->rchild);
}

void Print(Tree T)
{
	inorder(T);
	cout << endl;
	preorder(T);
	cout << endl;
}

