class Node{
public:
    Node(int value)
        :value(value)
    {
    }
    int Value(){
        return this->value;
    }
    std::shared_ptr<Node> Left(){
        return this->left;
    }
    void Left(std::shared_ptr<Node> left){
        this->left = left;
    }
    std::shared_ptr<Node> Right(){
        return this->right;
    }
    void Right(std::shared_ptr<Node> right){
        this->right = right;
    }
    bool HasLeft(){
        return this->left ? true : false;
    }
    bool HasRight(){
        return this->right ? true : false;
    }

private:
    int value;
    std::shared_ptr<Node> left = nullptr ;
    std::shared_ptr<Node> right = nullptr;
};

using NodePtr = std::shared_ptr<Node>;

class BinarySearchTree{
public:
    void Insert(int value){
        if(!this->root){
            root = std::make_shared<Node>(value);
            return;
        }
        InsertProc(this->root, value);
    }
    vector<int> Preorder(){
        vector<int> result;
        this->PreorderProc(this->root, result);
        return result;
    }
    vector<int> Inorder(){
        vector<int> result;
        this->InorderProc(this->root, result);
        return result;
    }
private:
    NodePtr root = nullptr;

    void InsertProc(NodePtr node, int value){
        if(node->Value() < value){
            if(node->HasRight()){
                InsertProc(node->Right(), value);
            }else{
                node->Right(std::make_shared<Node>(value));
            }
        }else{
            if(node->HasLeft()){
                InsertProc(node->Left(), value);
            }else{
                node->Left(std::make_shared<Node>(value));
            }
        }
    }

    void PreorderProc(NodePtr current, vector<int>& list){
        list.push_back(current->Value());
        if (current->HasLeft()) PreorderProc(current->Left(), list);
        if (current->HasRight()) PreorderProc(current->Right(), list);
    }

    void InorderProc(NodePtr current, vector<int>& list){
        if(!current->HasLeft() && !current->HasRight()){
            list.push_back(current->Value());
            return;
        }
        if (current->HasLeft()){
            InorderProc(current->Left(), list);
        }
        list.push_back(current->Value());
        if (current->HasRight()) {
            InorderProc(current->Right(), list);
        }
    }

};

