void Insert(int key) {
	Node *y = NIL;
	Node *x = Root;
	Node *z;

	z = (Node*)malloc(sizeof(Node));
	z->data = key;
	z->left = NIL;
	z->right = NIL;

	while (x != NIL) {
		y = x;
		if (z->data < x->data) {
			x = x->left;
		}
		else {
			x = x->right;
		}
	}
	z->parent = y;
	if (y == NIL) {
		Root = z;
	}
	else {
		if (z->data < y->data) {
			y->left = z;
		}
		else {
			y->right = z;
		}
	}
}
