    int value;
    BinarySearchTree(int value) : value(value) {}
};

BinarySearchTree* insert(BinarySearchTree *root, BinarySearchTree *z) {
    BinarySearchTree *y = nullptr;
    BinarySearchTree *x = root;

    while (x != nullptr) {
        y = x;
        if (z->value < x->value) {
            x = x->left;
        } else {
            x = x->right;
        }
    }

    if (y == nullptr) {
        return z;
    } else if (z->value < y->value) {
        y->left = z;
    } else {
        y->right = z;
    }

    return root;
}

