    Node *x = root; // 現在の節点
    Node *z; // 挿入する節点

    // zの初期化
    z = new Node;
    z->key = k;
    z-> left = nil;
    z-> right = nil;

    // xを一番下まで持っていく
    while(x != nil){
        y = x;
        if(z->key < x->key){
            x = x->left;
        }else{
            x = x->right;
        }
    }

    z->parent = y;
    if(y == nil) root = z;
    else{
        if(z->key < y->key) y->left = z;
        else y->right = z;
    }
}

