using namespace std;

struct Node
{
    int data;
    Node *left,*right,*parent;
};
Node *Root,*NIL;

void insert(int k)
{
    Node *x=Root; //根节点
    Node *y=NIL; //x的父节点

    Node *z; //建立一个节点
    z=new Node;
    z->data=k;
    z->left=NIL;
    z->right=NIL;

    while(x!=NIL)
    {
        y=x; //更新父节点
        if(z->data<x->data) //根据大小寻找插入位置
            x=x->left;
        else
            x=x->right;
    }

    z->parent=y;
    if(y==NIL) //如果是空树，根结点就为z
        Root=z;
    else if(z->data<y->data) //根据大小插入
        y->left=z;
    else
        y->right=z;
}

void pre(Node *x)
{
    if(x==NIL) return;
    cout<<" "<<x->data;
    pre(x->left);
    pre(x->right);
}

void in(Node *x)
{
    if(x==NIL) return;
    pre(x->left);
    cout<<" "<<x->data;
    pre(x->right);
}

