	bst(int n)
	{
		nodes.resize(n);
	}

	int insert (int r, int n)
	{
		if (r == -1) {
			nodes[i].v = n;
			r = i++;
		} else if (nodes[r].v < n)
			nodes[r].r = insert(nodes[r].r, n);
		else
			nodes[r].l = insert(nodes[r].l, n);
		return r;
	}
	void insert (int n)
	{
		root = insert(root, n);
	}
	void print(int r, v &buf)
	{
		if (r == -1)
			return;
		node n = nodes[r];
		buf.push_back(n.v);
		print(n.l, buf);
		out(' ', n.v);
		print(n.r, buf);
	}
	void print()
	{
		v buf;
		print(root, buf);
		out('\n', buf);
	}
};

