class BinTree;

template<typename T>
class Node {
    T value;
    Node<T> *parent, *left, *right;
    Node (T _value) : value(_value) {
        parent = nullptr;
        left = nullptr;
        right = nullptr;
    }
    Node (){
        parent = nullptr;
        left = nullptr;
        right = nullptr;
    }
    friend BinTree<T>;
    public:
    void inorder(std::vector<T> &ret) {
        if(left) left->inorder(ret);
        ret.push_back(value);
        if(right) right->inorder(ret);
    }
    void preorder(std::vector<T> &ret) {
        ret.push_back(value);
        if(left) left->preorder(ret);
        if(right) right->preorder(ret);
    }
    void postorder(std::vector<T> &ret) {
        if(left) left->postorder(ret);
        if(right) right->postorder(ret);
        ret.push_back(value);
    }
};

template<typename T> 
class BinTree{
    Node<T> *root;
    size_t size;
