        Node<T> *y = nullptr, *x = root;
        while(x) {
            // std::cout << x << '\n';
            y = x;
            if(z->value < x->value) {
                x = x->left;
            }
            else {
                x = x->right;
            }
        }
        z->parent = y;
        if(y == nullptr) {
            root = z;
        }
        else if(z->value < y->value) {
            y->left = z;
        }
        else {
            y->right = z;
        }
    }
    public:
    BinTree() {
        root = nullptr;
        size = 0;
    }
    bool empty() {return size == 0;}
    void insert(T x) {
        Node<T> *z = new Node<T>(x);
        insert_main(z);
    }
    void preorder(std::vector<T> &ret) {root->preorder(ret);}
    void inorder(std::vector<T> &ret) {root->inorder(ret);}
