	struct Node
	{
		int key;
		Node* parent;
		Node* left;
		Node* right;

		Node(int k)
			: key(k)
			, parent(nullptr)
			, left(nullptr)
			, right(nullptr)
		{}
	};

	Node* root = nullptr;

	void Insert(int key)
	{
		auto n = new Node(key);

		if (root == nullptr)
		{
			root = n;
			return;
		}

		Node* current = root;
		Node* parent = current;
		bool right = true;
		while (current != nullptr)
		{
			parent = current;
			if (current->key < key)
			{
				current = current->right;
				right = true;
			}
			else
			{
				current = current->left;
				right = false;
			}
		}

		n->parent = parent;
		if (right)
		{
			parent->right = n;
		}
		else
		{
			parent->left = n;
		}
	}

	void Inorder(Node* n)
	{
		if (n == nullptr)
			return;

		Inorder(n->left);
		std::cout << ' ' << n->key;
		Inorder(n->right);
	}

	void Preorder(Node* n)
	{
		if (n == nullptr)
			return;

		std::cout << ' ' << n->key;
		Preorder(n->left);
		Preorder(n->right);
	}
}

