struct Node{
  int key;
  Node *r, *l, *p;
};

Node *root, *NIL;

void insert(int k){
  Node *x = root,*y = NIL, *z;

  z = (Node *)malloc(sizeof(Node));
  z->key = k;
  z->l = NIL;
  z->r = NIL;

  while(x != NIL){
    y = x;
    if(z->key < x->key){
      x = x->l;
    }
    else{
      x = x->r;
    }
  }

  z->p = y;
  if(y == NIL){
    root = z;
  }
  else{
    if(z->key < y->key){
      y->l = z;
    }
    else{
      y->r = z;
    }
  }
}

void inorder(Node *u){
  if(u == NIL) return;
  inoder(u->l);
  printf(" %d", u->key);
  inorder(u->r);
}

void preoder(Node *u){
  if(u == NIL) return;    
  printf(" %d", u->key);    
  preoder(u->l);
  preoder(u->r);
}


