struct node{
    int key;
    node* parent,*left,*right;
};
node *root=NULL;
node * pre;
void Insert(int key){
    node * temp=new node;
    temp->key=key;
    temp->left=NULL;
    temp->right=NULL;

    if(root==NULL){
        root=temp;
        return ;
    }
    else{
        pre=root;
        while(1){
            if (key<pre->key){
                if (pre->left==NULL){
                    pre->left=temp;
                    temp->parent=pre;
                    return;
                }
                else
                    pre=pre->left;
            }
            else if(key > pre->key){
                if (pre->right==NULL){
                    pre->right=temp;
                    temp->parent=pre;
                    return;
                }
                else
                    pre=pre->right;
            }
            else
                return;
        }
    }
}
