	node() :key(0), left(NULL), right(NULL), parent(NULL) {};
	node(int n) :key(n), left(NULL), right(NULL), parent(NULL) {};
};

class tree {
public:
	node *root;
	tree() :root(NULL) {};
	tree(node *n) :root(n) {};
	void insert(int n) {
		node N(n);
		this->insert(N);
	};
	void insert(node n) {
		node *y = NULL;
		node *x = root;
		while (x != NULL) {
			y = x;
			if (n.key<x->key) x = x->left;
			else x = x->right;
		}
		n.parent = y;
		if (y == NULL) root = new node(n);
		else if (n.key < y->key) y->left = new node(n);
		else y->right = new node(n);
	};
	void Pre() {
		tree t1(root->left), t2(root->right);
		cout << " " << root->key;
		if (t1.root != NULL) t1.Pre();
		if (t2.root != NULL) t2.Pre();
	};
	void Ino() {
		tree t1(root->left), t2(root->right);
		if (t1.root != NULL) t1.Ino();
		cout << " " << root->key;
		if (t2.root != NULL) t2.Ino();
	};
	void Pos() {
		tree t1(root->left), t2(root->right);
		if (t1.root != NULL) t1.Pos();
		if (t2.root != NULL) t2.Pos();
		cout << " " << root->key;
	};
};

