struct binary_tree {
    int root = -1;
    int n = 0;
    vi key, left, right, parent;
    binary_tree() {}
    void insert(int z_value) {
        n++;
        int y = -1;
        int x = root;
        while (x != -1) {
            y = x;
            if (z_value < key[x]) {
                x = left[x];
            } else {
                x = right[x];
            }
        }
        int z = SZ(key);
        key.PB(z_value);
        left.PB(-1);
        right.PB(-1);
        parent.PB(-1);
        if (y == -1) {
            root = z;
        } else if (z_value < key[y]) {
            left[y] = z;
            parent[z] = y;
        } else {
            right[y] = z;
            parent[z] = y;
        }
    }
    void print() {
        vector<bool> visited(n, false);
        int now = root;
        vector<int> ans(0);
        while (now != -1) {
            if (left[now] != -1 and visited[left[now]] == false) {
                now = left[now];
                continue;
            }
            if (visited[now] == false) {
                visited[now] = true;
                ans.PB(key[now]);
            }
            if (right[now] != -1 and visited[right[now]] == false) {
                now = right[now];
                continue;
            }
            now = parent[now];
        }
        cout << " ";
        PRINT(ans);
        visited.assign(n, false);
        now = root;
        ans = {};
        while (now != -1) {
            if (visited[now] == false) {
                visited[now] = true;
                ans.PB(key[now]);
            }
            if (left[now] != -1 and visited[left[now]] == false) {
                now = left[now];
                continue;
            }
            if (right[now] != -1 and visited[right[now]] == false) {
                now = right[now];
                continue;
            }
            now = parent[now];
        }
        cout << " ";
        PRINT(ans);
    }
};

