  Node* N=nullptr;
  int n;cin >> n;
  for(int i=0;i<n;i++){
    string s;cin >> s;
    if(s=="insert"){
      int z;cin >> z;
      insert(N,z);
    }else{
      tree_print(N);
    }
  }
}

