using namespace std;

struct Node{
    int value;
    Node *parent, *left, *right;
};
Node *head;

void insertNode(int value){
    Node *x = head;
    Node *y;  //表示父节点
    while (x != NULL){
        y = x;
        if (value < x->value){
            x = x->left;
        }
        else{
            x = x->right;
        }
    }
    Node *z = new(Node);
    z->value = value;
    z->left = NULL;
    z->right = NULL;
    if (y != NULL){
        if (z->value < y->value){
            y->left = z;
        }
        else{
            y->right = z;
        }
        z->parent = y;
    } else{
        head = z;
    }
}

void inOrder(Node *x){
    if (x != NULL){
        inOrder(x->left);
        printf(" %d", x->value);
        inOrder(x->right);
    }
}

void preOrder(Node *x){
    if (x != NULL){
        printf(" %d", x->value);
        preOrder(x->left);
        preOrder(x->right);
    }
}

