    if (!root) return;
    inorder(root->left);
    cout << " " << root->val;
    inorder(root->right);
}

void preorder(TreeNode* root)
{
    if (!root) return;
    cout << " " << root->val;
    preorder(root->left);
    preorder(root->right);
}

