    }
  }
  Free(T);
  return 0;
}
void Inorder(node* X){
  if(X != NULL){
    Inorder(X->left);
    std::cout << " " << X->key;
    Inorder(X->right);
  }
}
void Preorder(node* X){
  if(X != NULL){
    std::cout << " " << X->key;
    Preorder(X->left);
    Preorder(X->right);
  }
}
void Free(node* X){
  if(X != NULL){
    Free(X->left);
    Free(X->right);
    delete X;
  }
}
void Insert(int key){
  node *x, *y, *S;
  if(T->key == -1){
    T->key = key;
    return;
  }
  S = new node;
  S->key = key, S->parent = S->left = S->right = NULL;
  x = T;
  while(x != NULL) y = x = (key < x->key ? x->left : x->right);
  S->parent = y;
  (S->key < y->key ? y->left : y->right) = S;
}

