#include <bits/stdc++.h>
using namespace std;
struct Tree{
  Tree *left, *right;
  int32_t *key;
  Tree(): left(nullptr), right(nullptr), key(nullptr){}
  void insert(int32_t x){
    if(Tree::key==nullptr) Tree::key=new int32_t(x);
    else{
      if(x<*Tree::key){
        if(Tree::left==nullptr) Tree::left=new Tree;
        Tree::left->insert(x);
      } else{
        if(Tree::right==nullptr) Tree::right=new Tree;
        Tree::right->insert(x);
      }
    }
  }
  bool find(int32_t x){
    if(Tree::key==nullptr) return false;
    if(x<*Tree::key){
      if(Tree::left==nullptr) return false;
      return Tree::left->find(x);
    } else{
      if(Tree::right==nullptr) return false;
      return Tree::right->find(x);
    }
  }
  void preorder(){
    if(Tree::key!=nullptr){
      cout<<' '<<*Tree::key;
      if(Tree::left!=nullptr) Tree::left->preorder();
      if(Tree::right!=nullptr) Tree::right->preorder();
    }
  }
  void inorder(){
    if(Tree::key!=nullptr){
      if(Tree::left!=nullptr) Tree::left->inorder();
      cout<<' '<<*Tree::key;
      if(Tree::right!=nullptr) Tree::right->inorder();
    }
  }
};

int32_t main(){
  size_t n; cin>>n;
  Tree tree;
  string cmd;
  int32_t key;
  for(int i=0; i<n; ++i){
    cin>>cmd;
    switch(cmd[0]){
      case 'i': cin>>key; tree.insert(key); break;
      case 'f': cin>>key; cout<<(tree.find(key)?"yes\n":"no\n"); break;
      default: tree.inorder(); cout<<'\n'; tree.preorder(); cout<<'\n';
    }
  }
}

