        if(x->left != nullptr){
            preorder(x->left);
        }
        if(x->right != nullptr){
            preorder(x->right);
        }
    }

    void inorder(shared_ptr<Node>& x){
        if(x->left != nullptr){
            inorder(x->left);
        }
        cout << ' ' << x->key;
        if(x->right != nullptr){
            inorder(x->right);
        }
    }

public:
    Set():size(0){}
    void insert(int val){
        if(size == 0){
            root = make_shared<Node>(nullptr, nullptr, nullptr, val);
        } else {
            shared_ptr<Node> y = nullptr;
            shared_ptr<Node> x = root;
            while(x != nullptr){
                y = x;
                if(val < x->key){
                    x = x->left;
                } else {
                    x = x->right;
                }
            }

            if(val < (y->key)){
               y->left = make_shared<Node>(y,nullptr,nullptr,val);
            } else {
               y->right = make_shared<Node>(y,nullptr,nullptr,val);
            }
        }
        ++size;
    }


    void print(){
        if(size == 0) return;
        inorder(root);
        cout << endl;
        preorder(root);
        cout << endl;
    }

