Node tMin(Node x)
{
  while(x->L!=NULL)
    {
      x=x->L;
    }
  return x;
}

Node tMax(Node x)
{
    while(x->R!=NULL)
    {
      x=x->R;
    }
  return x;
}

Node tSea(Node x, int k)
{
  if(x==NULL||k==x->key)return x;
  if(k<x->key)return tSea(x->L,k);
  else return tSea(x->R,k);
}

Node tSor(Node x)
{
  Node y;

  if(x->R!=NULL)return tMin(x->R);

  y=x->parent;
  while(y!=NULL&&x==y->R)
    {
      x=y;
      y=y->parent;
    }
  return y;
}

void tDel(Node z)
{
  Node y; // node to be deleted
  Node x; // child of y

  if(z->L==NULL||z->R==NULL)y=z;
  else y=tSor(z);

  if(y->L!=NULL)x=y->L;
  else x=y->R;

  if(x!=NULL)x->parent=y->parent;
  if(y->parent==NULL)root=x;
  else if(y==y->parent->L)y->parent->L=x;
  else  y->parent->R=x;

  if(y!=z)z->key=y->key;
}

