void insert(int key) {
  Node *newNode, *current;

  newNode = malloc(sizeof(Node));
  newNode->key = key;

  if (root == NULL) {
    root = newNode;
    return;
  }

  current = root;
  while (1) {
    if (newNode->key < current->key) {
      if (current->left == NULL) {
	current->left = newNode;
	break;
