void PrintPreorder(NODE tree)
{
    if (IsEmpty(tree))
    return;

    printf(" %d", tree->node->A);

    if (!IsEmpty(tree->node->left))
    PrintPreorder(tree->node->left);   

    if (!IsEmpty(tree->node->right))
    PrintPreorder(tree->node->right);  
}



void PrintInorder(NODE tree)
{
    if (IsEmpty(tree))
    return;

    if (!IsEmpty(tree->node->left))
    PrintInorder(tree->node->left);    

    printf(" %d", tree->node->A);

    if (!IsEmpty(tree->node->right))
    PrintInorder(tree->node->right);   
}


void Free(NODE tree)
{
    if (IsEmpty(tree))
    free(tree);
    else
    {
    Free(tree->node->left);
    Free(tree->node->right);
    free(tree->node);
    free(tree);
    }
}





bool Search(NODE tree, int key)
{
    while (1)
    {
    if (IsEmpty(tree))
        return false;
    else if (key < tree->node->A)
        tree = tree->node->left;
    else if (key > tree->node->A)
        tree = tree->node->right;
    else
        return true;
    }
}



void Insert(NODE tree, int item)
{
    while (1)
    {
    if (IsEmpty(tree))
    {
        CreateLeaf(tree, item);
        break;
    }
    else if (item < tree->node->A)
        tree = tree->node->left;
    else if (item > tree->node->A)
        tree = tree->node->right;
    }
}


bool IsEmpty(NODE tree)
{
    return tree->node == NULL;
}



void CreateLeaf(NODE leaf, int item)
{
    leaf->node = (Node)malloc(sizeof(struct Node));
    leaf->node->A = item;
    leaf->node->left = NewTree();
    leaf->node->right = NewTree();
}





NODE NewTree(void)
{
    NODE empty = (NODE)malloc(sizeof(struct NODE));
    empty->node = NULL;
    return empty;
}

