	Tree tree = new Tree();

	Scanner scanner = new Scanner(System.in);

	int n = scanner.nextInt();

	for (int i = 0; i < n; i++) {
	    String command = scanner.next();

	    if (command.equals("insert")) {
		int key = scanner.nextInt();
		tree.insert(key);
	    } else {
		tree.inorderWalk();
		tree.preorderWalk();
	    }
	}
    }
}

