struct node{
  struct node *right;
  struct node *left;
  struct node *parent;
  int key;
};
typedef struct node * Node;
#define NIL NULL

Node root;

Node treeMinimum(Node x){
  while(x->right != NIL){
    x=x->left;
  }
  return x;
}

Node treeMaximum(Node x){
  while(x->right != NIL){
    x=x->right;
  }
  return x;
}

Node treeSearch(Node u, int k){

  if(u==NIL || k==u->key){
    return u;
  }
  if(k<u->key){
    return treeSearch(u->left,k);
  }
  else
    return treeSearch(u->right,k);
}

Node treeSuccessor(Node x){
  Node y;
  if(x->right != NIL){
    return treeMinimum(x->right);
  }
  y=x->parent;
  while(y!=NIL && x==y->right){
    x=y;
    y=y->parent;
  }
}

void treeDelete(Node z){
  Node y; // node to be deleted
  Node x; // child of y
  if(z->left==NIL || z->right==NIL){
    y=z;
  }
  else
    y=treeSuccessor(z);

  if(y->left != NIL){
    x=y->left;
  }
  else x=y->right;

  if(x != NIL){
    x->parent=y->parent;
  }

  if(y->parent==NIL){
    x=root;
  }
  else if(y==y->parent->left){
    y->parent->left=x;
  }
  else y->parent->right=x;

  if(y != z){
    z->key=y->key;
  }
}

