record(struct node *r, struct node *p)
{
	if (p->key == r->key)
		return;
	else if (p->key < r->key) {
		if (r->car == NULL)
			r->car = p;
		else
			record(r->car, p);
	} else {
		if (r->cdr == NULL)
			r->cdr = p;
		else
			record(r->cdr, p);
	}
}

