    while (node->parent != NULL) {
        i++;
        node = node->parent;
    }
    return i;
}

Node nodeSibling(Node node) {
    if (node->parent == NULL)	
        return NULL; // NULL POINTER

    Node parentNode = node->parent;

    if (parentNode->left == node && parentNode->right != NULL)
        return parentNode->right;

    if (parentNode->right == node && parentNode->left != NULL)
        return parentNode->left;

    // no sibling
    return NULL; // NULL POINTER
}

void insertNodeIntoTree(Node *p_root, Node newNode) {
    Node nodeParent = NULL;
    Node nodeX = *p_root;

    // find its place
    //- it should be a leaf
    while (nodeX != NULL) {
        nodeParent = nodeX;
        if (newNode->key < nodeX->key)
            nodeX = nodeX->left;  // <
        else
            nodeX = nodeX->right; // >=
    }
    newNode->parent = nodeParent;


    // put it in as a leaf
    if (nodeParent == NULL) {// tree is empty
//        printf("inserting as root\n");
        *p_root = newNode;
    }
    else if (newNode->key < nodeParent->key) {
//        printf("inserting to the left of %d\n", nodeParent->key);
        nodeParent->left = newNode;
    }
    else {
//        printf("inserting to the right of %d\n", nodeParent->key);
        nodeParent->right = newNode;
    }
}

void preParse(Node node) {
    if (node == NULL)
        return;

    printf(" %d", node->key);
    preParse(node->left);
    preParse(node->right);
}

void inParse(Node node) {
    if (node == NULL)
        return;

    inParse(node->left);
    printf(" %d", node->key);
    inParse(node->right);
}

void postParse(Node node) {
    if (node == NULL)
        return;

    postParse(node->left);
    postParse(node->right);
    printf(" %d", node->key);
}






