  Node p = NULL, q = root, newNode;

  newNode = malloc(sizeof(struct node));
  newNode->key = key;
  newNode->left = NULL;
  newNode->right = NULL;

  while(q != NULL){
    p = q;

    if(newNode->key < q->key)q =q->left;
    else q = q->right;
  }

  newNode->p = p;

  if(p == NULL)root =newNode;
  else if(newNode->key < p->key)p->left =newNode;
  else p->right =newNode;
}



