Node treeMaximum(Node x){
  while(x->right != NIL)x = x->right;
  return x;
}

// 木から key の値を持つノードを探す
Node treeSearch(Node x, int k){
  while(x != NIL && k != x->key){
    if(k < x->key)x = x->left;
    else x = x->right;
  }
  return x;
}

