// 構造体を宣言
struct Node {
    // 自分のなまえ
    int key;
    // 子(右) 子(左) 親 のポインタ
    struct Node *right, *left, *parent;
};
typedef struct Node Node;

Node *root, *NIL;

void insert(int k) {
    // 構造体yに構造体NILを代入
    Node *y = NIL;
    // 構造体xに構造体rootを代入
    Node *x = root;
    // 構造体zを出す
    Node *z;

    // 構造体zと構造体分のメモリを確保して新しく宣言した構造体を対応させる
    z = (Node *)malloc(sizeof(Node));
    // 構造体zのkeyにkを入力する
    z->key   = k;
    // 構造体zの子を両方NILにする
    z->left  = NIL;
    z->right = NIL;

    // 一番下に行くまで(番兵が出るまで)分岐して行く
    while(x != NIL) {
        // 構造体yに構造体xを代入する
        y = x;
        // 参照するキーより小さかったら左に、大きかったら右の子へ移動する
        if(z->key < x->key) {
            x = x->left;
        } else {
            x = x->right;
        }
    }

    // 構造体yを構造体zのparentに入れる
    // z->parent = y;
    // 構造体yがNILだった場合(木が空の場合)rootにzを代入する
    if(y == NIL) {
        root = z;
    }
    // 挿入するところのノードと挿入するやつでどっちが大きいかによって左右分ける
    // 挿入するやつの方が小さかったら左、大きかったら右
    else {
        if( z->key < y->key) {
            y->left = z;
        } else {
            y->right = z;
        }
    }
}

// 中間順巡回 (Inorder Tree Walk)
void inorder(Node *u) {
    if(u == NIL) return;
    inorder(u->left);
    printf(" %d",u->key);
    inorder(u->right);
}
// 先行順巡回 (Preorder Tree Walk)
void preorder(Node *u) {
    if(u == NIL) return;
    printf(" %d",u->key);
    preorder(u->left);
    preorder(u->right);
}

int main(void) {
    int n, i, x;
    // 文字列を取得するための配列を宣言
    char com[16];
    // ノードの個数を取得
    scanf("%d",&n);

    for(i=0;i<n;i++) {
        // 文字列を取得
        scanf("%s",com);
        // 文字列がinsertだった場合
        if(!strcmp(com,"insert")) {
            // 挿入する数字を取得
            scanf("%d",&x);
            // 挿入する
            insert(x);
        }
        // 文字列がprintだった場合
        else if(!strcmp(com,"print")) {
            // 中間順巡回(inorder tree walk)を出力
            inorder(root);
            printf("\n");
            // 先行順巡回(preorder tree walk)を出力
            preorder(root);
            printf("\n");
        }
    }

    return 0;
}

