struct node{
  struct node *right;
  struct node *left;
  struct node *oya;
  int key;
};

typedef struct node *Node;

Node root;

Node min(Node a){
  while(a -> left != NULL){
    a = a -> left;
  }
  return a;
}

Node search(Node i, int k){
  if(i -> key > k){
    if(i -> left == NULL){
      return NIL;
    }
    return search(i -> right, k);
  }
  return i;
}

Node successor(Node x){
  Node y;
  if(x -> right != NIL){
    return min(x -> right);
  }
  y = x -> oya;
  while( y != NIL && x == y -> right){
    x = y;
    y = y -> oya;
    return y;
  }
}

void delete(Node d){
  Node x, y;
  if(d != NIL){
    if(d -> left == NIL || d -> right == NIL){
      y = d;
      if(d -> left != NIL){
	x = y -> right;
      }else{
	x = y -> right;
      }
    }else if( x != NIL){
      x -> oya = y -> oya;
      if (y -> oya == NIL){
	root = x;
      } else if(y = y -> oya -> left){
	y -> oya -> left = x;
      } else {
	y -> oya -> right = x;
      }

    }
  }

  if(y != d){
    d -> key = y -> key;
    d -> oya = y -> oya;
    d -> left = y -> left;
    d -> right = y -> right;
  }
}

