  Node x = root;
  Node y = NIL;
  Node z;

  z = malloc(sizeof(struct node));
  z -> key = k;
  z -> left = NIL;
  z -> right = NIL;

  while(x != NIL){
    y = x;
    if(z -> key < x -> key){
      x = x -> left;
    } else {
      x = x -> right;
    }
  }
  z -> oya = y;
  if(y == NIL){
    root = z;
  } else if (z -> key < y-> key){
    y -> left = z;
  } else {
    y -> right = z;
  }
}

