// 要素追加
// ツリーのルートを返す
NODE *insert_tree(NODE *root,int k){
    NODE *new_root = root;
    NODE *y = NULL; // x の親
    NODE *x = root;
    NODE *z = make_node(k);

    while( x != NULL ){
        y = x; // 親を設定
        if( z->key < x->key ){
            x = x->left; // 左の子へ移動
        }else{
            x = x->right; // 右の子へ移動
        }
    }

    if( y == NULL){ // T が空の場合
        new_root = z;
    }else if( z->key < y->key){
        y->left = z; // z を y の左の子にする
    }else{
        y->right = z; // z を y の右の子にする
    }

    return new_root;
}

// 内容表示
void print_tree(NODE *root){
    print_tree_inorder(root);
    print_tree_preorder(root);
}
// 中間順巡回
void print_tree_inorder(NODE *node){
    static NODE *stack_node[MAX_NODE*2];
    static int   stack_type[MAX_NODE*2];// 0:巡回 1:表示
    int sp;
    NODE *tmp_node;

    stack_node[0]=node;
    stack_type[0]=0;
    sp = 1;
    while(sp>0){
        sp--;
        tmp_node = stack_node[sp];
        if(tmp_node==NULL)continue;
        switch(stack_type[sp]){
            case 0: //巡回
                stack_node[sp]=tmp_node->right;
                stack_type[sp]=0; //巡回
                sp++;
                stack_node[sp]=tmp_node;
                stack_type[sp]=1; //表示
                sp++;
                stack_node[sp]=tmp_node->left;
                stack_type[sp]=0; //巡回
                sp++;
                break;
            case 1: //表示
                printf(" %d",tmp_node->key);
                break;
            default:
                break;
        }
    }
    printf("\n");
}

// 先行順巡回
void print_tree_preorder(NODE *node){
    static NODE *stack[MAX_NODE];
    int sp;
    NODE *tmp_node;

    stack[0]=node;
    sp = 1;
    while(sp>0){
        tmp_node = stack[--sp];
        if(tmp_node==NULL)continue;
        stack[sp++]=tmp_node->right;
        stack[sp++]=tmp_node->left;
        printf(" %d",tmp_node->key);
    }
    printf("\n");
}

