void initNode(Node *n){
    n->data = -1;
    n->parent = NULL;
    n->left = NULL;
    n->right = NULL;
}

void insert(Node *node, Node *tree, int loc){
    Node *temp;
    copyNode(temp,node);
    Node *parent = NULL;
    Node *current = tree;
    while(current != NULL && current->data != -1){
        parent = current;
        if(temp->data < current->data)
            current = current->left;
        else
            current = current->right;
    }
    temp->parent = parent;
    if(parent == NULL)
        copyNode(tree,temp);
    else if(node->data < parent->data){
        copyNode(&tree[loc],temp);
        parent->left = &tree[loc];
    }
    else{
        copyNode(&tree[loc],temp);
        parent->right = &tree[loc];
    }
}

