int main(void){
	int m, k;
	char s[10];
	int i;

	BinTree t;
	BinTree *T = &t;
	T->root = NULL;
	T->size = 0;

	scanf("%d", &m);
	for (i = 0; i < m; i++){
		scanf("%s", s);
		if (!strcmp(s, "insert")){
			scanf("%d", &k);
			T->bn[T->size] = initBinNode(k);
			BinNode *z = &(T->bn[T->size]);
			T->size++;
			Insert(T, z);
		}
		else if (!strcmp(s, "print")){
				InorderPrint(T->root);
				printf("\n");
				PreorderPrint(T->root);
				printf("\n");
		}
	}

	return 0;
