BinNode initBinNode(int v){
	BinNode z;
	z.key = v;
	z.parent = NULL;
	z.left = NULL;
	z.right = NULL;

	return z;
}

void Insert(BinTree *T, BinNode *z){
	BinNode *x, *y;

	y = NULL;
	x = T->root;
	while (x != NULL){
		y = x;
		if (z->key < x->key)
			x = x->left;
		else
			x = x->right;
	}
	z->parent = y;

	if (y == NULL)
		T->root = z;
	else if (z->key < y->key)
		y->left = z;
	else
		y->right = z;
}

void InorderPrint(BinNode *p){
	if (p != NULL){
		InorderPrint(p->left);
		printf(" %d", p->key);
		InorderPrint(p->right);
	}
}

void PreorderPrint(BinNode *p){
	if (p != NULL){
		printf(" %d", p->key);
		PreorderPrint(p->left);
		PreorderPrint(p->right);
	}
}

