  tree c;

  c=malloc(sizeof(struct node));
  c->s=x;
  c->L=NULL;
  c->R=NULL;

  while(a!=NULL){
    b=a;
    if(c->s < a->s){
      a=a->L;
    }
    else a=a->R;
  }

  c->oya=b;
  if(b==NULL) run=c;
  else{
    if(c->s < b->s){
      b->L=c;
    }
    else b->R=c;
  }
