tree serch(int z){
  tree x=run;

  while(x!=NULL){
    if(x->s==z) return x;
    else if(z < x->s) x=x->L;
    else x=x->R;
  }
  return NULL;
}


tree treeSuccessor(tree x){
  tree y;

  if(x->R!=NULL) return treeMinimum(x->R);
  y=x->oya;
  while(y!=NULL&&x==y->R){
    x=y;
    y=y->oya;
  }
  return y;
}

