  if(b->L!=NULL) a=b->L;
  else a=b->R;

  if(a!=NULL) a->oya=b->oya;

  if(b->oya==NULL) run=a;
  else if(b==b->oya->L) b->oya->L=a;
  else b->oya->R=a;

  if(b!=z) z->s=b->s;
