  while(u != NIL && k != u->key){
    if(k<u->key)
      u=u ->left;
    else u=u->right;
  }
  return u;
}

Node treeSuccessor(Node x){
  Node m;
  if(x -> right != NIL)
    return treeMinimum(x->right);
  m = x->parent;
  while(m!= NIL && x == m -> right){
    x = m;
    m = m->parent;
  }
  return m;

}

