			x = x->left;	// 左の子へ移動
		else
			x = x->right;	// 右の子へ移動
	}

	if (y == NULL)	// T が空の場合
		TREE = z;	// Tの根 = z
	else if(z->key < y->key)
		y->left = z; // z を y の左の子にする
	else
		y->right = z; // z を y の右の子にする
}

