int binarySearch(int key,int n){
  int left=0,right = n,mid=0;
  while(left < right){
    mid = (left + right)/2;
    if(A[mid] == key){
      return 1;
    }if(A[mid] < key) {
      left = mid+1;
    } else if(key < A[mid]){
      right = mid;
    }
  }
  return 0;
}

