{
  if (node != NULL) {
    inorder_traverse(node->left);
    printf(" %d", node->key);
    inorder_traverse(node->right);
  }
}

void tree_destroy(struct node* node)
{
  if (node != NULL) {
    tree_destroy(node->left);
