    y=x;
    if(z->key < x->key){
      x=x->left;
    }
    else{
      x=x->right;
    }
  }
  z->parent=y;
  if(y==NIL){
    root = z;
  }
  else if(z->key < y->key){
    y->left=z;
  }
  else y->right=z;

}

