struct node{
  struct node *right;
  struct node *left;
  struct node *parent;
  int key;
};
typedef struct node * Node;
#define NIL NULL

Node root;

Node tree_left_max(Node x){
	Node left_biggest, parent_node;

	left_biggest = x->left;
	parent_node = x;
	while(left_biggest->right != NULL){
		parent_node = left_biggest;
	    left_biggest = left_biggest->right;
	}
	return left_biggest;
}

Node tree_search(Node u, int k){

	if(u->key > k){
		if(u->left==NIL){  /* もし左側になければ，keyはない */
			return NIL;
		}
		return tree_search(u->left, k);
	}
	/* 自分より大きい値ならば，右側 */
	if(u->key < k){
		if(u->right == NULL){
			return NULL;      /* もし右側になければ，keyはない */
		}
		return tree_search(u->right, k);
	}

	return u;
}

int tree_position(Node z){
	int direction;
	if(z->parent->right == z){
		  direction = 1;
	  } else if(z->parent->left == z){
		  direction = -1;
	  } else {
		  direction = 0;
	  }
	return direction;
}

void tree_delete(Node z){
  Node left_max;
  int direction; //if z is left child: -1, right child: 1, other: 0
  direction = tree_position(z);
  if(z != NIL){
	  if(z->left == NIL || z->right == NIL){
             /* 左か右，どちらかがNULLであった場合(両方NULLの場合も含む) */
		  if(z->left == NIL){
                 /* 親のポインタを変更する */
			  if(direction == -1){
                     z->parent->left = z->right;
			  }
              if(direction == 1){
                     z->parent->right = z->right;
              }
              if(direction == 0){
                     root = z->right;
              }
		  } else {
               /* 親のポインタを変更する */
              if(direction == -1){
                  z->parent->left = z->left;
              }
              if(direction == 1){
                  z->parent->right = z->left;
              }
              if(direction == 0){
                  root = z->left;
              }
           }
             free(z);
         } else {
             /* 両者ともNULLでなかった場合 */
        	left_max = tree_left_max(z);

             /* left_maxの値をz_keyに代入し，left_maxは左側の枝を入れる */
             z->key = left_max->key;
             if(direction==-1){
                 z->parent->left = left_max->left;
             } else {
                 z->parent->right = left_max->left;
             }
          free(left_max);
          free(z);
       }
    }


}

Node new_node(Node n, int k){
	Node z;

	z = malloc(sizeof(struct node));
	z->key = k;
	z->left = NIL;
	z->right = NIL;
	z->parent = n;
	return z;
}

void insert(int k, Node x){

  if(x->key > k){
	  if(x->left != NIL){
		  insert(x->left, k);
	  } else {
		  /* 左側に追加する */
		  x->left = new_node(x, k);
	  }
  } else {
  /* kが現在のnodeの値以上の場合 */
	  if(x->right != NIL){
		  insert(x->right, k);
	  } else {
		  /* 右側に追加する */
		  x->right=new_node(x, k);
	  }
   }
  return;
}

