	if(u != NIL){
		inorder(u->left);
		printf("%d", u->key);
		inorder(u->right);
	}
}

void preorder(Node u){
	printf(u->key);
	if (u->left != NIL){
		preorder(u->left);
	}

	if (u->right != NIL){
	    preorder(u->right);
	}
}


