		m = sc.nextInt();
		T = new int[m];
		for(int i=0; i<m; i++) {
			order = sc.next();
			if(order.equals("print")) {
				inorder(root);
				System.out.println();
				preorder(root);
			}else {
				T[i] = sc.nextInt();
				insert(T[i]);
			}
		}
	}
