class Solve {
	private long m;
	private ICommand[] commands;

	public Solve(final long m, final ICommand[] commands)
	{
		this.m = m;
		this.commands = commands;
	}

	public void solve()
	{
		Tree T = new Tree();

		for(ICommand command: commands)
		{
			command.exec(T);
		}
	}
}
