    public static class BinaryTree {
        boolean isEmpty;
        int node;
        BinaryTree left;
        BinaryTree right;

        public BinaryTree() {
            isEmpty = true;
        }

        public BinaryTree(int node) {
            this.node = node;
            isEmpty = false;
            left = new BinaryTree();
            right = new BinaryTree();
        }

        public void insert(int z) {
            if (this.isEmpty) {
                this.node = z;
                this.isEmpty = false;
                this.left = new BinaryTree();
                this.right = new BinaryTree();
                return;
            }

            if (z < this.node) {
                left.insert(z);
            } else {
                right.insert(z);
            }
        }

        public void show() {
            if (this.isEmpty) return;

            System.out.println(this.node);
            this.left.show();
            this.right.show();
        }

        public String toStringPreorder() {
            if (this.isEmpty) return "";
            String l = " " + this.left.toStringPreorder();
            String r = " " + this.right.toStringPreorder();

            return (this.node + l + r).trim();
        }

        public String toStringInorder() {
            if (this.isEmpty) return "";
            String l = this.left.toStringInorder() + " ";
            String r = " " + this.right.toStringInorder();

            return (l + this.node + r).trim();
        }
    }

}

