class Node {
  Node left;
  Node right;
  int value;

  public Node (int x) {
    this.value = x;
    this.left = null;
    this.right = null;
  }

  public void insert(int x) {
    if (x < this.value) {
      if (left == null) {
        left = new Node(x);
        return;
      } else {
        left.insert(x);
        return;
      }
    } else {
      if (right == null) {
        right = new Node(x);
        return;
      } else {
        right.insert(x);
        return;
      }
    }
  }

  public void getStringInOrder(StringBuilder buf){
    if (left != null) {
      left.getStringInOrder(buf);
    }

    process(buf);

    if (right != null) {
      right.getStringOrder(buf);
    }
  }

  public void getStringPreOrder(StringBuilder buf){
    process(buf);

    if (left != null) {
      left.getStringPreOrder(buf);
    }

    if (right != null) {
      right.getStringPreOrder(buf);
    }
  }


  private void process(StringBuilder buf) {
    buf.append(value);
    buf.append(" ");
  }
}

class BinaryTree {
