                inPerse(root);
                sb.append(System.lineSeparator());
                prePerse(root);
                sb.append(System.lineSeparator());
            }
        }
        System.out.print(sb);
    }

    static void intsert(int key){

        Node y = NIL;
        Node x = root;
        Node z = new Node(key);

        while(x != NIL){
            y = x;
            if(z.key < x.key){
                x = x.left;
            }else{
                x = x.right;
            }
        }
        z.parent = y;

        if(y == NIL){
            root = z;
        }else if(z.key < y.key){
            y.left = z;
        }else{
            y.right = z;
        }
    }

    static void prePerse(Node u){

        if(u == NIL) return;
        sb.append(" ").append(u.key);
        prePerse(u.left);
        prePerse(u.right);
    }

    static void inPerse(Node u){

        if(u == NIL) return;
        inPerse(u.left);
        sb.append(" ").append(u.key);
        inPerse(u.right);
    }

    static class Node {
        int key;
        Node parent, left, right;

        public Node(int key) {
            this.key = key;
            parent = NIL;
            left = NIL;
            right = NIL;
        }
    }
}

