	private class BST {

		private Node<Integer> rootNode;
		public BST() {
			rootNode = null;
		}

		public void insert(Node<Integer> node) {			
			Node<Integer> parent = null;
			Node<Integer> cur = rootNode;
			while (cur != null) {
				parent = cur;
				if (node.key < cur.key) {
					cur = cur.left;
				} else {
					cur = cur.right;
				}
			}
			node.parent = parent;
			if (parent == null) {
				rootNode = node;
			} else if (node.key < parent.key) {
				parent.left = node;
			} else {
				parent.right = node;
			}
		}

