                String[] line = in.readLine().split(" ");
                if (line[0].charAt(0) == 'i') {
                    Node node = new Node(Long.parseLong(line[1]));
                    btree.insert(node);
                } else {
                    btree.print();
                }
            }
        } catch (IOException e) {
            e.printStackTrace();
        }
    }
}

