	//二分探索木にキーkeyを持つ節を挿入するメソッド
	public Node insert(Integer key) {
		Node p = root;
		//parentは現在注目している節の親
		Node parent = null;
		//pがparentの左の子ならtrue,右の子ならfalseを返す
		boolean isLeftChild = false;
		//注目している節がある限り処理を繰り返す
		while(p != null) {
			int result = key.compareTo(p.data);
			//節とキーを比較し、等しければすでに登録されているためnullを返す
			if(result == 0) {
				return null;
			//キーの方が小さければ左部分木
			}else if(result < 0) {
				parent = p;
				isLeftChild = true;
				p = p.left;
			//キーの方が大きければ右部分木
			}else {
				parent = p;
				isLeftChild = false;
				p = p.right;
			}
		}
		//新しい節を適切な場所に挿入する
		//新しい節を割り当てる
		Node newNode = new Node(key);
		if(parent == null) {
			//新しい節は根となるため、rootに新しい節を代入する
			root = newNode;
		}else if(isLeftChild) {
			//節parentの左の子になる
			parent.left = newNode;
		}else {
			//節parentの右の子になる
			parent.right = newNode;
		}
		return newNode;
	}
