		Scanner cin = new Scanner(System.in);
		int q_len = cin.nextInt();
		String cmd;
		int val;
		bst<Integer> bst = new bst<Integer>();
		while(q_len > 0) {
			cmd = cin.next();
			if(cmd.equals("insert")) {
				val = cin.nextInt();
				bst.insert(val);
