	public Node right;
	public Node p;
	public Node(int key){
		this.key = key;
	}
	public static Node insert(Node T, Node z){
		Node y = null;
		Node x = T;
		while(x != null){
			y = x;
			if(z.key < x.key){
				x = x.left;
			}else{
				x = x.right;
			}
		}
		z.p = y;

		if(y == null){
			T = z;
		}else if(z.key < y.key){
			y.left = z;
		}else{
			y.right = z;
		}
		return T;
	}
	public static String strInOrder(Node z){
		String str = "";
		if(z == null){
			return str;
		}
		if(z.left != null){
			str += strInOrder(z.left) + " ";
		}
		str += z.key;
		if(z.right != null){
			str += " " + strInOrder(z.right);
		}
		return str; 
	}
	public static String strPreOrder(Node z){
		String str = "";
		if(z == null){
			return str;
		}
		str += z.key;
		if(z.left != null){
			str += " " + strPreOrder(z.left);
		}
		if(z.right != null){
			str += " " + strPreOrder(z.right);
		}
		return str; 
	}
}

