                var next = curNode.Id > id ? Dir.Left : Dir.Right;

                if(curNode.Children[next] == null){
                    curNode.Children[next] = Nodes[id];
                    Nodes[id].Parent = curNode.Children[next];
                    break;
                }

                curNode = curNode.Children[next];
            }
        }

        public List<Node> Order(TreeWalk tw){
            var res = new List<Node>();

            Action<Node> parse = null;
            parse = node =>{
                if(node == null) return;

                if(tw == TreeWalk.PreOrder) res.Add(node);
                parse(node.Children[Dir.Left]);
                if(tw == TreeWalk.InOrder) res.Add(node);
                parse(node.Children[Dir.Right]);
                if(tw == TreeWalk.PostOrder) res.Add(node);
            };
            parse(Nodes.Values.Single(n => n.Parent == null));

            return res;
        }
    }

    public enum Dir{
        Left,
        Right
    }

    public class Node{
        public int Id;
        public Node Parent;
        public Dictionary<Dir, Node> Children;

        public Node(int id){
            Id = id;
            Children = new Dictionary<Dir, Node>(){{Dir.Left, null}, {Dir.Right, null}};
        }
    }
}

