class BinaryTree{
	List<Node> nodes;
	public BinaryTree(){
		nodes= new List<Node>();
	}
	void findParent(Node n, int k){
		if(n.Left==null && k < n.Key ){
			n.Left=nodes.Count-1;
			return;
		}else if(n.Right==null && k > n.Key){
			n.Right=nodes.Count-1;
			return;
		}
		if(n.Key>k)
			findParent(nodes[(int)n.Left],k);
		else
			findParent(nodes[(int)n.Right],k);
	}
	public void AddNode(int key){
		if(nodes.Count==0)
			nodes.Add(new Node(key));
		else{
			nodes.Add(new Node(key));
			findParent(nodes[0],key);
		}
	}

