    public static node[] Insert(int v ,node[] T)
    {
        node[] U = new node[T.Length + 1];

        for(int i = 0; i < T.Length; i++) {
            U[i] = T[i];
        }
        U[T.Length] = new node();
        U[T.Length].key = v;

        node y = null;
        node x = GetRoot(T);

        while(x != null) {
            y = x;
            if(v < x.key) x = x.leftChild;
            else x = x.rightChild;
        }
        U[T.Length].parent = y;

        if(y == null) {
            U[0] = new node();
            U[0].key = v;
        } else if (v < y.key) {
            y.leftChild = U[T.Length];
        } else {
            y.rightChild = U[T.Length];
        }

        return U;
    }

    public static void Print(node[] T)
    {
        preorderKey = new int[T.Length];
        inorderKey = new int[T.Length];
        precount = 0;
        incount = 0;

        node root = GetRoot(T);
        Inorder(root, T);
        Preorder(root, T);

        StringBuilder sb = new StringBuilder();
        for(int i = 0; i < T.Length; i++) {
            sb.Append(" " + inorderKey[i]);
        }
        Console.WriteLine(sb.ToString());
        sb = new StringBuilder();
        for(int i = 0; i < T.Length; i++) {
            sb.Append(" " + preorderKey[i]);
        }
        Console.WriteLine(sb.ToString());

    }

    public static void Preorder(node t, node[] tree)
    {
        preorderKey[precount++] = t.key;
        if(t.leftChild != null) Preorder(t.leftChild, tree);
        if(t.rightChild != null) Preorder(t.rightChild, tree);
    }

    public static void Inorder(node t, node[] tree)
    {
        if(t.leftChild != null) Inorder(t.leftChild, tree);
        inorderKey[incount++] = t.key;
        if(t.rightChild != null) Inorder(t.rightChild, tree);
    }

    public static node GetRoot(node[] T)
    {
        if ( T ==  null ) return null;
        if ( T.Length == 0) return null;

        node u = T[0];
        while(u.parent != null) {
            u = u.parent;
        }

        return u;
    }

}

