    public enum TreeWalk{
        PreOrder,
        InOrder,
        PostOrder
    }

    public class Tree{
        public Dictionary<int, Node> Nodes = new Dictionary<int, Node>();
        public Node Root;

        public void Add(int id){
            Nodes.Add(id, new Node(id));

            if(Root == null){
                Root = Nodes[id];
                return;
            }

            var curNode = Root;
            while(true){
                if(curNode.Id > id){
                    if(curNode.Left == null){
                        curNode.Left = Nodes[id];
                        Nodes[id].Parent = curNode.Left;
                        break;
                    }
                    curNode = curNode.Left;
                }

                if(curNode.Id < id){
                    if(curNode.Right == null){
                        curNode.Right = Nodes[id];
                        Nodes[id].Parent = curNode.Right;
                        break;
                    }
                    curNode = curNode.Right;
                }
            }

        }

        public List<Node> Order(TreeWalk tw){
            var res = new List<Node>();

            Action<Node> parse = null;
            parse = node =>{
                if(node == null) return;

                if(tw == TreeWalk.PreOrder) res.Add(node);
                parse(node.Left);
                if(tw == TreeWalk.InOrder) res.Add(node);
                parse(node.Right);
                if(tw == TreeWalk.PostOrder) res.Add(node);
            };
            parse(Nodes.Single(n => n.Value.Parent == null).Value);

            return res;
        }
    }

    public class Node{
        public int Id;
        public Node Parent;
        public Node Left;
        public Node Right;

        public Node(int id){
            Id = id;
        }
    }
