class Binary_Tree {

	List<Node> nodes;

	public Binary_Tree() {
		nodes = new List<Node>();
	}

	public void Add_Node(int k) {

		if(nodes.Count == 0) {
		nodes.Add(new Node(k));
		} else {
			nodes.Add(new Node(k));
			search_parent(nodes[0], k);
		}
	}

	void search_parent(Node node, int k) {

		if(node.left == null && node.key > k) {
			node.left = nodes.Count - 1;
			return;
		} else if(node.right == null && node.key < k) {
			node.right = nodes.Count - 1;
		//	Console.WriteLine(nodes.Count);
			return;
		}

		if(node.key > k) {
			search_parent(nodes[(int)node.left], k);
		} else {
			search_parent(nodes[(int)node.right], k);
		}
	}

	void inorder_walk(Node node) {

		if(node.left != null) {
			inorder_walk(nodes[(int)node.left]);
		}

		Console.Write(" {0}", node.key);

		if(node.right != null) {
			inorder_walk(nodes[(int)node.right]);
		}
	}

	void preoder_walk(Node node) {

		Console.Write(" {0}", node.key);

		if(node.left != null) {
			preoder_walk(nodes[(int)node.left]);
		}

		if(node.right != null) {
			preoder_walk(nodes[(int)node.right]);
		}
	}

	public void show() {
		inorder_walk(nodes[0]);
		Console.WriteLine();
		preoder_walk(nodes[0]);
		Console.WriteLine();
	}

}

