        class BinaryTree
        {
            public class Node
            {
                internal int val;
                internal Node left, right, parent;

                internal Node() : this(0, null) { }

                internal Node(int val, Node parent)
                {
                    this.val = val;
                    this.parent = parent;
                    left = right = null;
                }
            }

            Node root;

            public BinaryTree()
            {
                root = null;
            }

            public void Insert(int elem)
            {
                if (root == null)
                {
                    root = new Node(elem, null);
                    return;
                }

                Node n = root;
                Node p = null;
                while (n != null)
                {
                    p = n;
                    if (n.val > elem) n = n.left;
                    else n = n.right;
                }

                n = new Node(elem, p);
                if (p.val > elem) p.left = n;
                else p.right = n;
            }

            public void PrintPreorder(Node n)
            {
                if (n == null) return;
                Console.Write(" " + n.val);
                PrintPreorder(n.left);
                PrintPreorder(n.right);
