            Node x = _root;
            Node y = null;
            while (x != null) {
                y = x;
                x = key < x.Key ? x.Left : x.Right;
            }

            Node z = new Node(key, parent: y);
            if (z.Key < y.Key)
                y.Left = z;
            else
                y.Right = z;
        }

