        {
            nodes = new List<Node>();
        }

        public void Insert(int x)
        {
            if (nodes.Count == 0) Insert(x, -1);
            else Insert(x, 0);
        }

        private void Insert(int x, int parent)
        {
            if (parent == -1) nodes.Add(NewNode(x));
            else
            {
                if (nodes[parent].value > x)
                {
                    if (nodes[parent].left == -1)
                    {
                        nodes.Add(NewNode(x));
                        nodes[parent].left = nodes.Count - 1;
                    }
                    else Insert(x, nodes[parent].left);
                }
                else
                {
                    if (nodes[parent].right == -1)
                    {
                        nodes.Add(NewNode(x));
                        nodes[parent].right = nodes.Count - 1;
                    }
                    else Insert(x, nodes[parent].right);
                }
            }
        }

