namespace Binary_search_trees
{
    class Binary_Search_Tree_I
    {
        class BinaryTree
        {
            public class Node
            {
                internal int val;
                internal Node left, right, parent;

                internal Node() : this(0, null) { }

                internal Node(int val, Node parent)
                {
                    this.val = val;
                    this.parent = parent;
                    left = right = null;
                }
            }

            Node root;

            public BinaryTree()
            {
                root = null;
            }

            public void Insert(int elem)
            {
                if (root == null)
                {
                    root = new Node(elem, null);
                    return;
                }

                Node n = root;
                Node p = null;
                while (n != null)
                {
                    p = n;
                    if (n.val > elem) n = n.left;
                    else n = n.right;
                }

                n = new Node(elem, p);
                if (p.val > elem) p.left = n;
                else p.right = n;
            }

            public void PrintPreorder(Node n)
            {
                if (n == null) return;
                Console.Write(" " + n.val);
                PrintPreorder(n.left);
                PrintPreorder(n.right);
            }

            public void PrintPreorder()
            {
                PrintPreorder(root);
                Console.WriteLine();
            }

            public void PrintInorder(Node n)
            {
                if (n == null) return;
                PrintInorder(n.left);
                Console.Write(" " + n.val);
                PrintInorder(n.right);
            }

            public void PrintInorder()
            {
                PrintInorder(root);
                Console.WriteLine();
            }
        }

        static void Main(string[] args)
        {
            var n = int.Parse(Console.ReadLine());
            var bt = new BinaryTree();
            var sw = new StreamWriter(Console.OpenStandardOutput()) { AutoFlush = false };
            Console.SetOut(sw);
            for (int i = 0; i < n; i++)
            {
                var line = Console.ReadLine();
                if (line.Length == 5) { bt.PrintInorder(); bt.PrintPreorder(); }
                else bt.Insert(int.Parse(line.Substring(7)));
            }

            Console.Out.Flush();
        }
    }
