                string input = Console.ReadLine();

                if (input[0] == 'i')
                {
                    string[] temp = input.Split(' ');
                    Insert(int.Parse(temp[1]));
                }
                else
                {
                    sb = new StringBuilder();
                    Inorder(root);
                    sb.AppendLine();
                    Preorder(root);
                    Console.WriteLine(sb);
                }
            }
        }

        static void Insert(int k)
        {
            Node x = root;
            Node y = null;
            Node z = new Node(k);

            while (x != null)
            {
                y = x;
                x = z.key < x.key ? x.left : x.right;
            }

            if (y != null)
            {
                if (z.key < y.key) y.left = z;
                else y.right = z;
            }
            else root = z;
        }

        static void Inorder(Node u)
        {
            if (u == null) return;

            Inorder(u.left);
            sb.Append(" " + u.key);
            Inorder(u.right);
        }

        static void Preorder(Node u)
        {
            if (u == null) return;

            sb.Append(" " + u.key);
            Preorder(u.left);
            Preorder(u.right);
        }
    }
}

