		public Node right, left, parent;
	}

	static Node NIL = new Node();
	static Node root = new Node();

	public static void insert(int k)
	{
		Node y = NIL;
		Node x = root;
		Node z;

		z = new Node();
		z.key = k;
		z.left = NIL;
		z.right = NIL;

		while (x != NIL) {
			y = x;
			if (z.key < x.key){
				x = x.left;
			} else {
				x = x.right;
			}
		}

		z.parent = y;
		if (y == NIL){
			root = z;
		} else {
			if (z.key < y.key){
				y.left = z;
			} else {
				y.right = z;
			}
		}
	}

	public static void inorder(Node u)
	{
		if (u == NIL) return;
		inorder(u.left);
		Console.Write(" {0}", u.key);
		inorder(u.right);
	}

	public static void preorder(Node u)
	{
		if (u == NIL) return;
		Console.Write(" {0}", u.key);
		preorder(u.left);
		preorder(u.right);
	}

	public static int Main()
	{
		int n, i, x;
		n = int.Parse(Console.ReadLine());

		for(i = 0; i < n; i++){
			string[] com = Console.ReadLine().Split(' ');
			if (com[0] == "insert"){
				x = int.Parse(com[1]);
				insert(x);
			} else if (com[0] == "print") {
				inorder(root);
				Console.Write("\n");
				preorder(root);
				Console.Write("\n");
			}
		}

		return 0;
	}
}

