function treeInsert(T, z) {
	var y = null;
	var x = T.filter(function(n){return n.p == null;})[0];
	while (x != null) {
		y = x;
		if (z.key < x.key)
			x = x.left;
		else
			x = x.right;
	}
	z.p = y;
	if (y == null)
		T.push(z);
	else if (z.key < y.key)
		y.left = z;
	else
		y.right = z;
}

