function allocNode(key) {
	p = {};
	p.key = key;
	p.left = null;
	p.right = null;
	return p;
}
function insert(p,c) {
	if (p === null) return c;
	if (c.key < p.key) p.left = insert(p.left,c);
	else p.right = insert(p.right,c);
	return p;
}
function inset(p,ary) {
	if (p === null) return;
	inset(p.left,ary);
	ary.push(p.key);
	inset(p.right,ary);
}
function preset(p,ary) {
	if (p === null) return;
	ary.push(p.key);
	preset(p.left,ary);
	preset(p.right,ary);
}
