package main

import (
	"bufio"
	"os"
	"fmt"
	"strconv"
)

type Node struct {
	value int
	left *Node
	right *Node
}


/****************************************************************
*関数insert():													*
*	 挿入される二分探索木のrootノードを表すポインタrootと				*
*	 挿入したいノードのvalueを引数に、適切な葉に新たなノードを挿入して、	*
*	 挿入された二分探索木のルートノードのポインタを返す関数				*
*****************************************************************/
func insert(root *Node, val int) *Node {

	// 二分探索木がまだ構築されていないときはここが呼び出される
	if root == nil {
		return &Node{val, nil,nil}
	}

	// すでにある二分探索木に対するノード（value: val）を挿入する
	// ここを抜けるとparentに挿入されるノードの親へのポインタが入っている
	// 変数nodeは、挿入すべき場所を探すための一時的なポインタ変数
	var parent *Node
	node := root
	for node != nil {
		parent = node
		if node.value > val {
			node = node.left
		} else {
			node = node.right
		}
	}

	// 新たなノードの挿入を実行
	if parent.value > val {
		parent.left = &Node{val, nil,nil}
	} else {
		parent.right = &Node{val, nil, nil}
	}

	// 二分探索木の根は変わらないのでそのまま返す
	return root
}

func printNodes(nodes []int) {
	// 木の走査によって得られたint型スライスを引数に、
	// 指定されたフォーマットに出力する関数
	writer := bufio.NewWriter(os.Stdout)
	for _, v := range nodes{
		writer.Write([]byte(fmt.Sprintf(" %d", v)))
	}
	writer.Write([]byte("\n"))
	writer.Flush()
}

func preorder(root *Node, memo []int) []int {
	// 引数rootが根となっている二分探索木に対して先行巡回によって
	// 各ノードをを舐めて、引数memoで与えられる空のスライスに書き込み、
	// 書き込まれた後のスライスを返す関数
	if root != nil {
		memo = append(memo, root.value)
		memo = preorder(root.left, memo)
		memo = preorder(root.right, memo)
	}
	return memo
}

func inorder(root *Node, memo []int) []int {
	// 引数rootが根となっている二分探索木に対して中間巡回によって
	// 各ノードをを舐めて、引数memoで与えられる空のスライスに書き込み、
	// 書き込まれた後のスライスを返す関数
	if root != nil {
		memo = inorder(root.left, memo)
		memo = append(memo, root.value)
		memo = inorder(root.right, memo)
	}
	return memo
}

func main() {
	var n int
	var root *Node
	scanner := bufio.NewScanner(os.Stdin)
	scanner.Split(bufio.ScanWords)
	scanner.Scan()
	n, _  = strconv.Atoi(scanner.Text())
	for i := 0; i < n; i++ {
		scanner.Scan()
		operation := scanner.Text()
		switch operation {
		case "insert":
			scanner.Scan()
			value, _ := strconv.Atoi(scanner.Text())
			root = insert(root, value)
		case "print":
			printNodes(inorder(root, []int{}))
			printNodes(preorder(root, []int{}))
		}
	}
}

package main

import "fmt"

type Node struct {
	value int
	left *Node
	right *Node
}

type BinaryTree struct {
	root *Node
}

func generateNode(val int) *Node {
	return &Node{val, new(Node), new(Node)}
}

func (t *BinaryTree) insert(val int) {
	if t.root == nil {
		t.root = generateNode(val)
	} else {
		t.root._insert(val)
	}
}

func (n *Node) _insert(val int) {
	if val <= n.value {
		if n.left != nil {
			n.left._insert(val)
		} else {
			n.right = generateNode(val)
		}
	} else {
		if n.right != nil {
			n.right._insert(val)
		} else {
			n.right = generateNode(val)
		}
	}
}

func (t *BinaryTree) printTree(input []int) {
	for _, v := range input {
		if v == 0 {
			continue
		}
		fmt.Printf(" %d", v)
	}
}

func preorder(root *Node, ans []int) []int {
	if root != nil {
		ans = append(ans, root.value)
		ans = preorder(root.left, ans)
		ans = preorder(root.right, ans)
	}
	return ans
}

func inorder(root *Node, ans []int) []int {
	if root != nil {
		ans = inorder(root.left, ans)
		ans = append(ans, root.value)
		ans = inorder(root.right, ans)
	}
	return ans
}

func main() {
	var (
		n int
		op string
		val int
	)
	bt := new(BinaryTree)
	fmt.Scan(&n)
	for i := 0; i < n; i++ {
		fmt.Scan(&op)
		switch op{
		case "insert":
			fmt.Scan(&val)
			bt.insert(val)
		case "print":
			bt.printTree(inorder(bt.root, []int{}) )
		fmt.Println()
			bt.printTree(preorder(bt.root, []int{}))
		fmt.Printf("\n")
		}
	}
}

