func Insert(root *node, value int) *node {

	if root == nil {
		return &node{value, nil, nil}
	}

	var parent *node
	anode := root
	for anode != nil {
		parent = anode
		if anode.key > value {
			anode = anode.left
		} else {
			anode = anode.right
		}
	}

	if parent.key > value {
		parent.left = &node{value, nil, nil}
	} else {
		parent.right = &node{value, nil, nil}
	}
	return root
