type Node struct {
	key                 int
	right, left, parent *Node
}

var root, NIL *Node

func Insert(k int) {
	var y *Node
	y = nil   // xの親
	x := root // 挿入先
	z := new(Node)
	z.key, z.left, z.right = k, nil, nil

	// 挿入先の探索
	for x != nil {
		y = x
		if z.key < x.key {
			x = x.left
		} else {
			x = x.right
		}
	}

	// 挿入ノードに関して、親と挿入先を設定する（挿入先の判断にはもう一度kyeチェックが必要）
	z.parent = y
	if y == nil {
		root = z
	} else {
		if z.key < y.key {
			y.left = z
		} else {
			y.right = z
		}
	}
}

func inorder(u *Node, res *[]int) {
	if u == nil {
		return
	}
	inorder(u.left, res)
	*res = append(*res, u.key)
	inorder(u.right, res)
}

func preorder(u *Node, res *[]int) {
	if u == nil {
		return
	}
	*res = append(*res, u.key)
	preorder(u.left, res)
	preorder(u.right, res)
}

