func insert(k int) {
	insertNode := &Node{Key: k}
	var x *Node = root
	var y *Node = nil

	for {
		if x==nil {
			break
		}
		y = x
		if insertNode.Key < x.Key {
			x = x.Left
		} else {
			x = x.Right
		}
