		return
	}
	inorder(u.Left)
	outKeys[pos] = u.Key
	pos ++
	inorder(u.Right)
}

func preorder(u *Node) {
	if u==nil {
		return
	}
	outKeys[pos] = u.Key
	pos ++
	preorder(u.Left)
	preorder(u.Right)
}

