// Tree tree
type Tree struct {
	root *Node
	keys []int
	i    int
	n    int
}

func (t *Tree) insert(key int) {
	t.n++
	node := Node{
		key:    key,
		parent: nil,
		left:   nil,
		right:  nil,
	}
	if t.root == nil {
		t.root = &node
		return
	}

	n := t.root
	var p *Node
	p = nil

	for n != nil {
		p = n
		if n.key < key {
			n = n.right
			continue
		}
		n = n.left
	}
	node.parent = p
	if p.key < key {
		p.right = &node
		return
	}
	p.left = &node
}

func (t *Tree) printPreOrders(n *Node) {
	if n == nil {
		return
	}
	t.keys[t.i] = n.key
	t.i++
	t.printPreOrders(n.left)
	t.printPreOrders(n.right)
}

func (t *Tree) printInOrders(n *Node) {
	if n == nil {
		return
	}
	t.printInOrders(n.left)
	t.keys[t.i] = n.key
	t.i++
	t.printInOrders(n.right)
}

// Node node
type Node struct {
	key    int
	parent *Node
	left   *Node
	right  *Node
}

func joinint(a []int, sep string) string {
	n := len(a)
	ss := make([]string, n)
	for i := 0; i < n; i++ {
		ss[i] = fmt.Sprintf("%d", a[i])
	}
	return strings.Join(ss, sep)
}

