func insert(v int) {
	var x, y *Node

	//x: 走査する初期値
	//y: xの親 = NIL
	x = root

	//z: 挿入するNode
	z := &Node{v, NIL, NIL, NIL}
	//zの親を求める
	for x != NIL {
		y = x
		if z.key < x.key {
			x = x.l
		} else {
			x = x.r
		}
	}

	z.p = y
	if y == NIL {
		root = z //木が空のときは、zをrootとする
	} else if z.key < y.key {
		y.l = z //zをyの左の子にする
	} else {
		y.r = z //zをyの右のことする
	}

}

