func preOrder(node *Node, accm []int) []int {
	if node == nil {
		return accm
	}
	accm = append(accm, node.key)
	accm = preOrder(node.left, accm)
	accm = preOrder(node.right, accm)
	return accm
}

func inOrder(node *Node, accm []int) []int {
	if node == nil {
		return accm
	}
	accm = inOrder(node.left, accm)
	accm = append(accm, node.key)
	accm = inOrder(node.right, accm)
	return accm
}

func postOrder(node *Node, accm []int) []int {
	if node == nil {
		return accm
	}
	accm = postOrder(node.left, accm)
	accm = postOrder(node.right, accm)
	accm = append(accm, node.key)
	return accm
}

func NewNode(key int) *Node {
	return &Node{
		key:    key,
		parent: nil,
		left:   nil,
		right:  nil,
	}
}

