func insert(node *Node, key int) *Node {

	var parent *Node
	n := node
	for n != nil {
		parent = n
		if n.key > key {
			n = n.left
		} else {
			n = n.right
		}
	}

	nn := &Node{
		key: key,
	}
	if parent == nil {
		return nn
	}
	nn.parent = parent
	if key < parent.key {
		parent.left = nn
	} else {
		parent.right = nn
	}

	return node
}

