func printList(accm []int) {
	buf := bufio.NewWriter(os.Stdout)
	for _, v := range accm {
		buf.Write([]byte(fmt.Sprintf(" %d", v)))
	}
	buf.Flush()
}

func print(node *Node) {
	var accm []int
	accm = inOrder(node, accm)
	printList(accm)
	fmt.Println()
	accm = make([]int, 0)
	accm = preOrder(node, accm)
	printList(accm)
	fmt.Println()
}

// solve
func solve(sc *bufio.Scanner) {
	var node *Node
	sc.Split(bufio.ScanWords)
	sc.Scan()
	n, _ := strconv.Atoi(sc.Text())
	for i := 0; i < n; i++ {
		sc.Scan()
		command := sc.Text()
		if command == "insert" {
			sc.Scan()
			value, _ := strconv.Atoi(sc.Text())
			node = insert(node, value)
		} else if command == "print" {
			print(node)
		}
	}
}

