void insert(ref Node node, int val)
{
  Node par, cur = node;
  while (cur !is null) {
    par = cur;
    if (val < cur.key) cur = cur.l;
    else cur = cur.r;
  }

  Node chi = new Node(val);
  if (par is null)
    node = chi;
  else if (val < par.key)
    par.l = chi;
  else
    par.r = chi;
}

int[] inorderWalk(Node node)
{
  int[] r;
  if (node.l !is null) r ~= inorderWalk(node.l);
  r ~= node.key;
  if (node.r !is null) r ~= inorderWalk(node.r);
  return r;
}

int[] preorderWalk(Node node)
{
  int[] r;
  r ~= node.key;
  if (node.l !is null) r ~= preorderWalk(node.l);
  if (node.r !is null) r ~= preorderWalk(node.r);
  return r;
}

