class BST:
    def __init__(self):
        self.root = None

    def insert(self, node):
        def helper(root):
            if root is None:
                root = node
            elif node.val < root.val:
                lr = helper(root.left)
                root.left = lr
            else:
                rr = helper(root.right)
                root.right = rr
            return root

        self.root = helper(self.root)

    def inorder(self):
        def helper(root):
            if root is None:
                return []
            else:
                return helper(root.left) + [root.val] + helper(root.right)
        return helper(self.root)

