class Node:
    def __init__(self, x):
        self.data = x
        self.left = None
        self.right = None

    def insert(node, x):
        if node == None:
            return Node(x)
        elif x == node.data:
            return node
        elif x < node.data:
            node.left = Node.insert(node.left, x)
        else:
            node.right = Node.insert(node.right, x)
        return node

    def find(node, x):
        if node.data == x:
