enum Tree<T: Ord + Display> {
    Nil,
    Node { 
        key: T, 
        left: Box<Tree<T>>, 
        right: Box<Tree<T>>,
    },
}

impl<T: Ord + Display> Tree<T> {
    fn insert_rec(&mut self, val: T) {
        match *self {
            Tree::Nil => {
                *self = Tree::Node{
                    key: val, 
                    left: Box::new(Tree::Nil), 
                    right: Box::new(Tree::Nil) };
            },
            Tree::Node{ ref key, ref mut left, ref mut right } => {
                if val < *key {
                    left.insert_rec(val);
                } else {
                    right.insert_rec(val);
                }
            },
        }
    }

    fn print_in(&self) {
        match *self {
            Tree::Nil => {;},
            Tree::Node{ ref key, ref left, ref right } => {
                left.print_in();
                print!(" {}", key);
                right.print_in();
            },
        }
    }

    fn print_pre(&self) {
        match *self {
            Tree::Nil => {;},
            Tree::Node{ ref key, ref left, ref right } => {
                print!(" {}", key);
                left.print_pre();
                right.print_pre();
            },
        }
    }
} 

