fn solve(input: &str) -> String {
    let mut iterator = input.split_whitespace();

    let m: usize = iterator.next().unwrap().parse().unwrap();

    let mut tree = BTS::new();
    let mut result = String::new();
    for _ in 0..m {
        let command = iterator.next().unwrap();
        if command == "insert" {
            let key: i64 = iterator.next().unwrap().parse().unwrap();
            tree.insert(key);
        } else {
            tree.print_in_order(&mut result);
            result.push('\n');
            tree.print_pre_order(&mut result);
            result.push('\n');
        }
    }

    return result;
}

enum BTS {
    Node {
        parent: Rc<RefCell<BTS>>,
        value: i64,
        left: Rc<RefCell<BTS>>,
        right: Rc<RefCell<BTS>>,
    },
    Nil
}

impl BTS {
    fn new() -> Self {
        BTS::Nil
    }

    fn insert(&mut self, new_value: i64) {
        match *self {
            BTS::Nil => {
                *self = BTS::Node {
                    parent: Rc::new(RefCell::new(BTS::Nil)),
                    value: new_value,
                    left: Rc::new(RefCell::new(BTS::Nil)),
                    right: Rc::new(RefCell::new(BTS::Nil)),
                }
            },
            BTS::Node {
                ref mut parent,
                ref mut value,
                ref mut left,
                ref mut right,
            } => {
                if new_value < *value {
                    left.borrow_mut().insert(new_value);
                } else {
                    right.borrow_mut().insert(new_value);
                }
            },
        }
    }

    fn print_in_order(&self, buf: &mut String) {
        match *self {
            BTS::Nil => {},
            BTS::Node {
                ref parent,
                ref value,
                ref left,
                ref right
            } => {
                left.borrow().print_in_order(buf);
                buf.push_str(&format!(" {}", value));
                right.borrow().print_in_order(buf);
            }
        }
    }

    fn print_pre_order(&self, buf: &mut String) {
        match *self {
            BTS::Nil => {},
            BTS::Node {
                ref parent,
                ref value,
                ref left,
                ref right
            } => {
                buf.push_str(&format!(" {}", value));
                left.borrow().print_pre_order(buf);
                right.borrow().print_pre_order(buf);
            }
        }
    }
}

